const curriculum=[{"id": 0, "title": "AI 基礎與學習方式", "en": "AI Foundations & Learning Paradigms", "terms": [{"id": "d0t0", "zh": "人工智慧", "en": "Artificial Intelligence, AI", "definition": "讓機器執行感知、推理、決策或生成等任務的研究與工程領域。", "lessonId": 24}, {"id": "d0t1", "zh": "通用人工智慧", "en": "Artificial General Intelligence, AGI", "definition": "通常指能跨廣泛任務遷移能力的人工智慧概念，目前沒有一致的操作性判定標準。", "lessonId": 24}, {"id": "d0t2", "zh": "機器學習", "en": "Machine Learning, ML", "definition": "從資料學習模式，以改善預測或決策，而非逐條手寫所有規則。", "lessonId": 24}, {"id": "d0t3", "zh": "深度學習", "en": "Deep Learning, DL", "definition": "以多層神經網路學習階層式資料表示的機器學習方法。", "lessonId": 24}, {"id": "d0t4", "zh": "生成式人工智慧", "en": "Generative Artificial Intelligence, Generative AI", "definition": "學習資料結構或分布以產生文字、影像、音訊等新內容。", "lessonId": 24}, {"id": "d0t5", "zh": "判別式模型", "en": "Discriminative Model", "definition": "直接學習分類邊界或輸入條件下的目標分布，例如邏輯斯回歸。", "lessonId": 24}, {"id": "d0t6", "zh": "生成式模型", "en": "Generative Model", "definition": "學習資料的生成結構或分布，可用於取樣新資料。", "lessonId": 24}, {"id": "d0t7", "zh": "監督學習", "en": "Supervised Learning", "definition": "使用帶目標答案的樣本學習輸入到輸出的對應。", "lessonId": 24}, {"id": "d0t8", "zh": "非監督學習", "en": "Unsupervised Learning", "definition": "在沒有目標標籤的資料中尋找群組、結構或表示。", "lessonId": 25}, {"id": "d0t9", "zh": "半監督學習", "en": "Semi-Supervised Learning", "definition": "結合少量有標籤與大量無標籤資料訓練模型。", "lessonId": 25}, {"id": "d0t10", "zh": "自監督學習", "en": "Self-Supervised Learning", "definition": "從資料本身建立學習目標，例如遮住文字後預測缺漏內容。", "lessonId": 25}, {"id": "d0t11", "zh": "強化學習", "en": "Reinforcement Learning, RL", "definition": "透過與環境互動的獎勵回饋學習長期決策策略。", "lessonId": 25}, {"id": "d0t12", "zh": "遷移學習", "en": "Transfer Learning", "definition": "把來源任務學到的表示或參數用於另一個任務。", "lessonId": 25}, {"id": "d0t13", "zh": "多任務學習", "en": "Multi-Task Learning", "definition": "聯合學習多個相關任務，利用共享表示改善資料效率。", "lessonId": 25}, {"id": "d0t14", "zh": "聯邦學習", "en": "Federated Learning", "definition": "資料留在各端，協調多端本地訓練並聚合更新；本身不保證隱私。", "lessonId": 25}, {"id": "d0t15", "zh": "持續學習", "en": "Continual Learning", "definition": "隨時間學習新任務，同時盡量保留舊能力。", "lessonId": 25}, {"id": "d0t16", "zh": "主動學習", "en": "Active Learning", "definition": "由學習系統挑選最值得人工標註的樣本。", "lessonId": 26}, {"id": "d0t17", "zh": "線上學習", "en": "Online Learning", "definition": "資料陸續到來時逐步更新模型，不等於單純把模型放上網路。", "lessonId": 26}, {"id": "d0t18", "zh": "離線學習", "en": "Offline Learning", "definition": "在事先收集的固定資料上學習；強化學習中則指使用既有互動紀錄。", "lessonId": 26}, {"id": "d0t19", "zh": "少樣本學習", "en": "Few-Shot Learning", "definition": "利用很少的目標任務樣本學習或適應任務。", "lessonId": 26}, {"id": "d0t20", "zh": "零樣本學習", "en": "Zero-Shot Learning", "definition": "在沒有該目標任務訓練樣本的條件下，透過既有知識或語意描述處理任務。", "lessonId": 26}, {"id": "d0t21", "zh": "後設學習", "en": "Meta-Learning", "definition": "跨任務學習如何快速適應新任務，也稱學習如何學習。", "lessonId": 26}, {"id": "d0t22", "zh": "課程學習", "en": "Curriculum Learning", "definition": "安排由易到難或其他有助學習的資料與任務順序。", "lessonId": 26}, {"id": "d0t23", "zh": "模仿學習", "en": "Imitation Learning", "definition": "利用專家示範學習行動策略，例如從駕駛示範學習轉向。", "lessonId": 26}], "level": "入門", "prerequisites": [], "case": "為工廠規劃外觀瑕疵辨識系統：有標籤圖片可做監督分類，無標籤圖片可先分群，機器人選動作則可能用強化學習。自監督預訓練可先利用大量無標籤影像，再以少量標籤遷移到瑕疵任務。", "exercises": ["列出分類、分群與決策三個任務，為各任務選擇學習方式並說明回饋來源。", "比較少樣本學習與少樣本提示：前者是學習設定，後者可在不更新權重下提供示例。", "設計跨新產品學習的流程，說明聯邦學習與持續學習分別解決什麼問題。"], "pitfall": "AGI 是能力概念，沒有單一公認測試；線上學習不是單純線上使用。", "lessonIds": [24, 25, 26], "sourceIds": [0, 1]}, {"id": 1, "title": "資料與前處理", "en": "Data & Preprocessing", "terms": [{"id": "d1t0", "zh": "資料集", "en": "Dataset", "definition": "用於分析、訓練或評估的一組有組織資料。", "lessonId": 27}, {"id": "d1t1", "zh": "樣本", "en": "Sample / Instance", "definition": "資料集中一個可供處理的實例，例如一張圖片或一筆交易。", "lessonId": 27}, {"id": "d1t2", "zh": "特徵", "en": "Feature", "definition": "供模型使用的輸入屬性或學得的表示。", "lessonId": 27}, {"id": "d1t3", "zh": "標籤", "en": "Label", "definition": "監督學習中與樣本對應的目標答案。", "lessonId": 27}, {"id": "d1t4", "zh": "目標變數", "en": "Target Variable", "definition": "模型要預測的變數，例如價格或故障類別。", "lessonId": 27}, {"id": "d1t5", "zh": "真實標準答案", "en": "Ground Truth", "definition": "評估時採用的參考答案；仍可能含標註誤差。", "lessonId": 27}, {"id": "d1t6", "zh": "訓練集", "en": "Training Set", "definition": "用來估計模型參數的資料子集。", "lessonId": 27}, {"id": "d1t7", "zh": "驗證集", "en": "Validation Set", "definition": "用來選模型、調整超參數及決定停止時機的資料子集。", "lessonId": 27}, {"id": "d1t8", "zh": "測試集", "en": "Test Set", "definition": "保留供最後評估的資料，不能反覆用來調參。", "lessonId": 27}, {"id": "d1t9", "zh": "資料切分", "en": "Data Splitting", "definition": "依時間、個體或群組等條件將資料分成不同用途的子集。", "lessonId": 27}, {"id": "d1t10", "zh": "資料標註", "en": "Data Annotation / Labeling", "definition": "替資料加上類別、框線、文字轉錄等參考資訊。", "lessonId": 27}, {"id": "d1t11", "zh": "資料清理", "en": "Data Cleaning", "definition": "處理錯值、重複紀錄與不一致格式等資料品質問題。", "lessonId": 27}, {"id": "d1t12", "zh": "資料前處理", "en": "Data Preprocessing", "definition": "將原始資料轉成模型可使用的形式。", "lessonId": 28}, {"id": "d1t13", "zh": "缺失值", "en": "Missing Value", "definition": "原應存在但未觀測或未記錄的資料值。", "lessonId": 28}, {"id": "d1t14", "zh": "缺失值填補", "en": "Missing Value Imputation", "definition": "以統計值或模型估計替代缺失值，估計規則應只從訓練集學得。", "lessonId": 28}, {"id": "d1t15", "zh": "離群值", "en": "Outlier", "definition": "相對多數資料顯著不同的觀測，不一定是錯誤。", "lessonId": 28}, {"id": "d1t16", "zh": "雜訊", "en": "Noise", "definition": "與目標訊號無關或干擾觀測的變動。", "lessonId": 28}, {"id": "d1t17", "zh": "資料增強", "en": "Data Augmentation", "definition": "以保留任務語意的轉換增加訓練變化，例如翻轉圖片。", "lessonId": 28}, {"id": "d1t18", "zh": "合成資料", "en": "Synthetic Data", "definition": "以程式、模擬器或模型產生的資料，仍需評估代表性與品質。", "lessonId": 28}, {"id": "d1t19", "zh": "特徵工程", "en": "Feature Engineering", "definition": "依領域知識建立或轉換模型輸入特徵。", "lessonId": 28}, {"id": "d1t20", "zh": "特徵選擇", "en": "Feature Selection", "definition": "從候選特徵中選出較有用的子集。", "lessonId": 28}, {"id": "d1t21", "zh": "特徵擷取", "en": "Feature Extraction", "definition": "從原始資料計算較有用的表示，例如影像邊緣或嵌入向量。", "lessonId": 28}, {"id": "d1t22", "zh": "正規化", "en": "Normalization", "definition": "依特定規則調整數值尺度或向量長度，具體公式依情境而定。", "lessonId": 28}, {"id": "d1t23", "zh": "標準化", "en": "Standardization", "definition": "常見為減平均值再除標準差，使特徵具有可比較尺度。", "lessonId": 28}, {"id": "d1t24", "zh": "獨熱編碼", "en": "One-Hot Encoding", "definition": "以一個位置為 1、其他位置為 0 的向量表示類別。", "lessonId": 29}, {"id": "d1t25", "zh": "類別不平衡", "en": "Class Imbalance", "definition": "不同類別的樣本量差異很大，可能使模型偏向多數類別。", "lessonId": 29}, {"id": "d1t26", "zh": "過採樣", "en": "Oversampling", "definition": "增加少數類別的抽樣或合成樣本以調整訓練分布。", "lessonId": 29}, {"id": "d1t27", "zh": "欠採樣", "en": "Undersampling", "definition": "減少多數類別樣本以調整訓練分布，可能損失資訊。", "lessonId": 29}, {"id": "d1t28", "zh": "資料洩漏", "en": "Data Leakage", "definition": "訓練或選模時用了實際預測時不應可見的資訊。", "lessonId": 29}, {"id": "d1t29", "zh": "資料偏差", "en": "Data Bias", "definition": "蒐集或標註方式造成資料不能充分代表目標情境。", "lessonId": 29}, {"id": "d1t30", "zh": "資料分布", "en": "Data Distribution", "definition": "描述資料取值及其機率的規律。", "lessonId": 29}, {"id": "d1t31", "zh": "分布偏移", "en": "Distribution Shift", "definition": "部署資料與訓練資料的統計分布不同。", "lessonId": 29}, {"id": "d1t32", "zh": "資料漂移", "en": "Data Drift", "definition": "輸入資料的特性隨時間改變。", "lessonId": 29}, {"id": "d1t33", "zh": "概念漂移", "en": "Concept Drift", "definition": "輸入與目標之間的關係隨時間改變。", "lessonId": 29}, {"id": "d1t34", "zh": "資料溯源", "en": "Data Provenance", "definition": "記錄資料來源、處理過程、版本與使用條件。", "lessonId": 29}], "level": "入門", "prerequisites": [0], "case": "用設備感測器預測故障：先依機台及時間切分資料，只用訓練集估計填補與標準化規則。少數故障樣本可在訓練集內重抽樣；維修後才產生的欄位不得用於事前預測。", "exercises": ["畫出一筆感測器樣本，標出特徵、標籤、缺值與來源。", "設計依機台與時間切分的方案，說明每一個轉換在哪個切分上估計。", "列出類別不平衡與資料漂移的檢查，建立可追溯的資料版本紀錄。"], "pitfall": "不可先對整份資料做標準化再切分；合成資料不會自動解決代表性不足。", "lessonIds": [27, 28, 29], "sourceIds": [0, 1]}, {"id": 2, "title": "數學與統計", "en": "Mathematics & Statistics", "terms": [{"id": "d2t0", "zh": "純量", "en": "Scalar", "definition": "單一數值，例如一筆樣本的損失。", "lessonId": 30}, {"id": "d2t1", "zh": "向量", "en": "Vector", "definition": "有順序的一組數值，例如三個特徵組成的表示。", "lessonId": 30}, {"id": "d2t2", "zh": "矩陣", "en": "Matrix", "definition": "二維數值陣列，常用來表示線性轉換。", "lessonId": 30}, {"id": "d2t3", "zh": "張量", "en": "Tensor", "definition": "多維陣列；模型中的批次影像可表示成四維張量。", "lessonId": 30}, {"id": "d2t4", "zh": "維度", "en": "Dimension", "definition": "可指軸數或向量分量數，使用時需說明語境。", "lessonId": 30}, {"id": "d2t5", "zh": "張量形狀", "en": "Tensor Shape", "definition": "各軸長度的序列，例如批次、通道、高度、寬度。", "lessonId": 30}, {"id": "d2t6", "zh": "點積", "en": "Dot Product", "definition": "對應分量相乘再相加，用於投影與相似度計算。", "lessonId": 30}, {"id": "d2t7", "zh": "矩陣乘法", "en": "Matrix Multiplication", "definition": "以列與行的點積組合矩陣，內側維度必須相同。", "lessonId": 30}, {"id": "d2t8", "zh": "轉置", "en": "Transpose", "definition": "交換矩陣的列與行，例如 2×3 矩陣轉置後成為 3×2。", "lessonId": 30}, {"id": "d2t9", "zh": "範數", "en": "Norm", "definition": "衡量向量或矩陣大小的函數，例如 L2 範數。", "lessonId": 30}, {"id": "d2t10", "zh": "特徵值", "en": "Eigenvalue", "definition": "線性轉換在特定方向上的縮放係數。", "lessonId": 30}, {"id": "d2t11", "zh": "特徵向量", "en": "Eigenvector", "definition": "經線性轉換後方向不變的非零向量。", "lessonId": 31}, {"id": "d2t12", "zh": "奇異值分解", "en": "Singular Value Decomposition, SVD", "definition": "將矩陣分解為正交方向與縮放，可用於低秩近似。", "lessonId": 31}, {"id": "d2t13", "zh": "機率分布", "en": "Probability Distribution", "definition": "為可能結果指定機率或機率密度。", "lessonId": 31}, {"id": "d2t14", "zh": "條件機率", "en": "Conditional Probability", "definition": "已知某事件發生時另一事件的機率。", "lessonId": 31}, {"id": "d2t15", "zh": "貝氏定理", "en": "Bayes’ Theorem", "definition": "用先驗與似然更新後驗：P(A|B)=P(B|A)P(A)/P(B)。", "lessonId": 31}, {"id": "d2t16", "zh": "最大概似估計", "en": "Maximum Likelihood Estimation, MLE", "definition": "選擇讓觀測資料最可能出現的參數。", "lessonId": 31}, {"id": "d2t17", "zh": "最大後驗估計", "en": "Maximum A Posteriori Estimation, MAP", "definition": "結合先驗與資料，選擇後驗機率最大的參數。", "lessonId": 31}, {"id": "d2t18", "zh": "期望值", "en": "Expected Value / Expectation", "definition": "隨機變數依機率加權的平均。", "lessonId": 31}, {"id": "d2t19", "zh": "變異數", "en": "Variance", "definition": "衡量隨機變數相對期望值的平方偏離。", "lessonId": 31}, {"id": "d2t20", "zh": "標準差", "en": "Standard Deviation", "definition": "變異數的平方根，單位與原資料相同。", "lessonId": 31}, {"id": "d2t21", "zh": "共變異數", "en": "Covariance", "definition": "衡量兩個變數共同變動的方向與大小。", "lessonId": 31}, {"id": "d2t22", "zh": "相關性", "en": "Correlation", "definition": "衡量變數關聯的程度；相關不代表因果。", "lessonId": 32}, {"id": "d2t23", "zh": "熵", "en": "Entropy", "definition": "衡量機率分布的不確定性，離散情況為負的 p log p 總和。", "lessonId": 32}, {"id": "d2t24", "zh": "交叉熵", "en": "Cross-Entropy", "definition": "以預測分布編碼真實分布的平均成本，常用於分類損失。", "lessonId": 32}, {"id": "d2t25", "zh": "KL 散度", "en": "Kullback–Leibler Divergence, KL Divergence", "definition": "衡量分布差異的非對稱量，不是一般距離。", "lessonId": 32}, {"id": "d2t26", "zh": "導數", "en": "Derivative", "definition": "函數對單一自變數的局部變化率。", "lessonId": 32}, {"id": "d2t27", "zh": "偏導數", "en": "Partial Derivative", "definition": "固定其他自變數時，函數對某一變數的變化率。", "lessonId": 32}, {"id": "d2t28", "zh": "梯度", "en": "Gradient", "definition": "由各偏導數組成的向量，指向函數局部增加最快的方向。", "lessonId": 32}, {"id": "d2t29", "zh": "鏈式法則", "en": "Chain Rule", "definition": "計算複合函數導數的規則，是反向傳播的基礎。", "lessonId": 32}, {"id": "d2t30", "zh": "Jacobian矩陣", "en": "Jacobian Matrix", "definition": "向量值函數各輸出對各輸入的一階偏導數矩陣。", "lessonId": 32}, {"id": "d2t31", "zh": "海森矩陣", "en": "Hessian Matrix", "definition": "純量函數的二階偏導數矩陣，用於描述局部曲率。", "lessonId": 32}, {"id": "d2t32", "zh": "凸最佳化", "en": "Convex Optimization", "definition": "在凸可行域上最小化凸函數；局部最小值也是全域最小值。", "lessonId": 32}], "level": "基礎", "prerequisites": [0], "case": "以三個特徵估計耗電量：x=[2,1,3]、w=[1,2,-1] 的點積為 1。若真值為 3，平方誤差為 4。對 L(w)=(w−3)²，導數為 2(w−3)，可用來決定更新方向。", "exercises": ["寫出一個純量、向量、矩陣與四維影像張量，逐軸標註形狀。", "計算簡單條件機率，說明相關性為何不能單獨證明因果。", "手算複合函數導數，畫出梯度、Jacobian與海森矩陣的輸入輸出維度。"], "pitfall": "KL 散度通常不對稱；維度可能指軸數或每軸長度，需說清楚。", "lessonIds": [30, 31, 32], "sourceIds": [0, 1]}, {"id": 3, "title": "傳統機器學習", "en": "Classical Machine Learning", "terms": [{"id": "d3t0", "zh": "分類", "en": "Classification", "definition": "預測離散類別，例如正常或故障。", "lessonId": 33}, {"id": "d3t1", "zh": "二元分類", "en": "Binary Classification", "definition": "目標有兩個互斥類別的分類任務。", "lessonId": 33}, {"id": "d3t2", "zh": "多類別分類", "en": "Multiclass Classification", "definition": "從三個以上互斥類別中選出一類。", "lessonId": 33}, {"id": "d3t3", "zh": "多標籤分類", "en": "Multilabel Classification", "definition": "一個樣本可同時具有多個標籤。", "lessonId": 33}, {"id": "d3t4", "zh": "回歸", "en": "Regression", "definition": "預測連續數值，例如溫度或價格。", "lessonId": 33}, {"id": "d3t5", "zh": "線性回歸", "en": "Linear Regression", "definition": "以輸入特徵的線性組合預測連續目標。", "lessonId": 33}, {"id": "d3t6", "zh": "邏輯斯回歸", "en": "Logistic Regression", "definition": "以線性分數經 sigmoid 或 softmax 建立分類機率模型。", "lessonId": 33}, {"id": "d3t7", "zh": "多項式回歸", "en": "Polynomial Regression", "definition": "用輸入的多項式特徵表達非線性關係。", "lessonId": 33}, {"id": "d3t8", "zh": "決策樹", "en": "Decision Tree", "definition": "以一連串特徵條件分割資料並作預測。", "lessonId": 33}, {"id": "d3t9", "zh": "隨機森林", "en": "Random Forest", "definition": "結合多棵帶抽樣與特徵隨機性的決策樹。", "lessonId": 33}, {"id": "d3t10", "zh": "支援向量機", "en": "Support Vector Machine, SVM", "definition": "以最大間隔建立決策邊界，可透過核函數表達非線性。", "lessonId": 34}, {"id": "d3t11", "zh": "最近鄰演算法", "en": "k-Nearest Neighbors, k-NN", "definition": "根據特徵空間中最近的 k 個樣本投票或平均作預測。", "lessonId": 34}, {"id": "d3t12", "zh": "樸素貝氏分類器", "en": "Naive Bayes Classifier", "definition": "在類別給定時假設特徵條件獨立的機率分類器。", "lessonId": 34}, {"id": "d3t13", "zh": "集成學習", "en": "Ensemble Learning", "definition": "組合多個模型的預測以改善效能或穩健性。", "lessonId": 34}, {"id": "d3t14", "zh": "自助聚合", "en": "Bootstrap Aggregating, Bagging", "definition": "在重抽樣資料上訓練多個模型，再聚合預測。", "lessonId": 34}, {"id": "d3t15", "zh": "提升法", "en": "Boosting", "definition": "依序加入模型以改善既有模型未處理好的部分。", "lessonId": 34}, {"id": "d3t16", "zh": "梯度提升", "en": "Gradient Boosting", "definition": "逐步擬合損失的負梯度方向，建立加法模型。", "lessonId": 34}, {"id": "d3t17", "zh": "分群", "en": "Clustering", "definition": "依相似性把資料分組，不需要預先給定每筆標籤。", "lessonId": 34}, {"id": "d3t18", "zh": "K 平均分群", "en": "K-Means Clustering", "definition": "交替分派最近中心與更新中心，以降低群內平方距離。", "lessonId": 34}, {"id": "d3t19", "zh": "階層式分群", "en": "Hierarchical Clustering", "definition": "透過逐步合併或分裂建立群組樹狀結構。", "lessonId": 34}, {"id": "d3t20", "zh": "密度式分群", "en": "Density-Based Clustering", "definition": "依資料密度尋找群組，可識別部分雜訊點。", "lessonId": 35}, {"id": "d3t21", "zh": "高斯混合模型", "en": "Gaussian Mixture Model, GMM", "definition": "以多個高斯分布的加權和表示資料分布。", "lessonId": 35}, {"id": "d3t22", "zh": "降維", "en": "Dimensionality Reduction", "definition": "以較少維度保留資料中重要資訊。", "lessonId": 35}, {"id": "d3t23", "zh": "主成分分析", "en": "Principal Component Analysis, PCA", "definition": "尋找資料變異最大的正交方向進行線性降維。", "lessonId": 35}, {"id": "d3t24", "zh": "異常偵測", "en": "Anomaly Detection", "definition": "找出相對正常模式明顯不同的樣本。", "lessonId": 35}, {"id": "d3t25", "zh": "推薦系統", "en": "Recommender System", "definition": "預測使用者可能感興趣的項目。", "lessonId": 35}, {"id": "d3t26", "zh": "協同過濾", "en": "Collaborative Filtering", "definition": "利用使用者與項目的互動模式推薦內容。", "lessonId": 35}, {"id": "d3t27", "zh": "矩陣分解", "en": "Matrix Factorization", "definition": "把大型互動矩陣分解成較低維的使用者與項目表示。", "lessonId": 35}, {"id": "d3t28", "zh": "時間序列預測", "en": "Time Series Forecasting", "definition": "利用按時間排列的歷史資訊預測未來數值。", "lessonId": 35}], "level": "基礎", "prerequisites": [1, 2], "case": "用表格資料預測設備故障，先以多數類別及邏輯斯回歸作基準，再比較隨機森林與梯度提升。若目標改為估計剩餘壽命，則是回歸；若只想找運轉型態，則是分群。", "exercises": ["為分類、回歸與分群各列一個輸入及預期輸出。", "比較決策樹、SVM 與 k-NN 的資料尺度需求和可解釋程度。", "設計推薦或時間序列專題，說明如何避免未來資訊進入訓練。"], "pitfall": "邏輯斯回歸通常用於分類；分群的群號不天然等於真實類別。", "lessonIds": [33, 34, 35], "sourceIds": [0, 1]}, {"id": 4, "title": "神經網路與網路層", "en": "Neural Networks & Layers", "terms": [{"id": "d4t0", "zh": "人工神經網路", "en": "Artificial Neural Network, ANN", "definition": "由可學習的連接與非線性運算單元組成的模型。", "lessonId": 36}, {"id": "d4t1", "zh": "神經元", "en": "Neuron", "definition": "通常先計算加權和與偏置，再套用激活函數的單元。", "lessonId": 36}, {"id": "d4t2", "zh": "感知器", "en": "Perceptron", "definition": "以線性分數及閾值作判斷的早期神經模型。", "lessonId": 36}, {"id": "d4t3", "zh": "多層感知器", "en": "Multilayer Perceptron, MLP", "definition": "由多個全連接層及非線性激活構成的前饋網路。", "lessonId": 36}, {"id": "d4t4", "zh": "輸入層", "en": "Input Layer", "definition": "接收資料並定義輸入表示的網路入口。", "lessonId": 36}, {"id": "d4t5", "zh": "隱藏層", "en": "Hidden Layer", "definition": "位於輸入與輸出之間，用來轉換表示的層。", "lessonId": 36}, {"id": "d4t6", "zh": "輸出層", "en": "Output Layer", "definition": "將內部表示轉成任務所需預測的層。", "lessonId": 36}, {"id": "d4t7", "zh": "全連接層", "en": "Fully Connected Layer / Dense Layer", "definition": "每個輸出與全部輸入相連，通常計算 Wx+b。", "lessonId": 36}, {"id": "d4t8", "zh": "權重", "en": "Weight", "definition": "控制輸入或連接影響程度的可學習係數。", "lessonId": 36}, {"id": "d4t9", "zh": "偏置", "en": "Bias", "definition": "加在線性轉換後的可學習偏移量。", "lessonId": 36}, {"id": "d4t10", "zh": "參數", "en": "Parameter", "definition": "由訓練估計的模型數值，例如權重與偏置。", "lessonId": 36}, {"id": "d4t11", "zh": "超參數", "en": "Hyperparameter", "definition": "在訓練外設定的配置，例如學習率、深度與批次大小。", "lessonId": 37}, {"id": "d4t12", "zh": "激活函數", "en": "Activation Function", "definition": "引入非線性或限制輸出範圍的函數。", "lessonId": 37}, {"id": "d4t13", "zh": "修正線性單元", "en": "Rectified Linear Unit, ReLU", "definition": "f(x)=max(0,x)，負區間的導數為零。", "lessonId": 37}, {"id": "d4t14", "zh": "帶洩漏修正線性單元", "en": "Leaky ReLU", "definition": "負區間保留小斜率的 ReLU 變體。", "lessonId": 37}, {"id": "d4t15", "zh": "高斯誤差線性單元", "en": "Gaussian Error Linear Unit, GELU", "definition": "以高斯累積分布平滑調整輸入，常見於 Transformer。", "lessonId": 37}, {"id": "d4t16", "zh": "Sigmoid 函數", "en": "Sigmoid Function", "definition": "1/(1+exp(-x))，將實數映射到 0 與 1 之間。", "lessonId": 37}, {"id": "d4t17", "zh": "雙曲正切函數", "en": "Hyperbolic Tangent, Tanh", "definition": "將實數映射到 -1 與 1 之間的平滑激活函數。", "lessonId": 37}, {"id": "d4t18", "zh": "Softmax 函數", "en": "Softmax Function", "definition": "將一組分數轉成總和為 1 的非負權重。", "lessonId": 37}, {"id": "d4t19", "zh": "前向傳播", "en": "Forward Propagation", "definition": "依網路結構從輸入逐層計算輸出與損失。", "lessonId": 37}, {"id": "d4t20", "zh": "反向傳播", "en": "Backpropagation", "definition": "沿計算圖以鏈式法則計算損失對參數的梯度。", "lessonId": 37}, {"id": "d4t21", "zh": "計算圖", "en": "Computational Graph", "definition": "以節點與邊記錄運算及其資料相依關係。", "lessonId": 37}, {"id": "d4t22", "zh": "自動微分", "en": "Automatic Differentiation", "definition": "依程式的基本運算及鏈式法則自動計算導數，不是有限差分。", "lessonId": 38}, {"id": "d4t23", "zh": "權重初始化", "en": "Weight Initialization", "definition": "訓練前設定參數初值，影響訊號與梯度尺度。", "lessonId": 38}, {"id": "d4t24", "zh": "批次正規化", "en": "Batch Normalization", "definition": "通常以批次統計量正規化激活；訓練與推論的統計處理不同。", "lessonId": 38}, {"id": "d4t25", "zh": "層正規化", "en": "Layer Normalization", "definition": "在每個樣本指定的特徵維度內正規化，通常不依賴批次統計。", "lessonId": 38}, {"id": "d4t26", "zh": "均方根正規化", "en": "Root Mean Square Normalization, RMSNorm", "definition": "依均方根縮放特徵，不包含一般 LayerNorm 的減平均值步驟。", "lessonId": 38}, {"id": "d4t27", "zh": "隨機失活", "en": "Dropout", "definition": "訓練時隨機屏蔽部分激活以減少共適應，推論時通常關閉。", "lessonId": 38}, {"id": "d4t28", "zh": "殘差連接", "en": "Residual Connection", "definition": "把輸入加到轉換輸出上，例如 y=x+F(x)。", "lessonId": 38}, {"id": "d4t29", "zh": "跳接", "en": "Skip Connection", "definition": "跨過中間層傳送資訊的連接，可採相加或串接等方式。", "lessonId": 38}, {"id": "d4t30", "zh": "梯度消失", "en": "Vanishing Gradient", "definition": "傳回較早層的梯度過小，造成學習緩慢。", "lessonId": 38}, {"id": "d4t31", "zh": "梯度爆炸", "en": "Exploding Gradient", "definition": "梯度數值過大，使更新不穩定或溢位。", "lessonId": 38}], "level": "基礎", "prerequisites": [2], "case": "對 x=[1,2]、w=[2,-1]、b=1，神經元線性分數為 1，ReLU 輸出也是 1。把輸入經兩個線性層但不加非線性，仍可合併為一個線性變換。加入殘差連接後，要先檢查相加張量形狀相容。", "exercises": ["用數字算一個神經元，標出權重、偏置與激活函數。", "畫出前向計算圖並指出哪些值需要反向傳播。", "比較 Dropout、BatchNorm、LayerNorm 與 RMSNorm 的功能及推論差異。"], "pitfall": "反向傳播負責算梯度，最佳化器才更新參數；正規化不同於正則化。", "lessonIds": [36, 37, 38], "sourceIds": [2]}, {"id": 5, "title": "訓練、最佳化與損失函數", "en": "Training, Optimization & Losses", "terms": [{"id": "d5t0", "zh": "模型訓練", "en": "Model Training", "definition": "以資料與學習目標調整模型參數的過程。", "lessonId": 39}, {"id": "d5t1", "zh": "訓練輪次", "en": "Epoch", "definition": "訓練資料完整被使用一次；串流取樣流程可能另作定義。", "lessonId": 39}, {"id": "d5t2", "zh": "批次", "en": "Batch", "definition": "一次運算中一起處理的一組樣本。", "lessonId": 39}, {"id": "d5t3", "zh": "批次大小", "en": "Batch Size", "definition": "每批樣本數，影響記憶體、梯度估計與吞吐量。", "lessonId": 39}, {"id": "d5t4", "zh": "小批次", "en": "Mini-Batch", "definition": "比完整資料集小的一批樣本，常用來估計梯度。", "lessonId": 39}, {"id": "d5t5", "zh": "更新步數", "en": "Training Step", "definition": "通常指一次最佳化器參數更新，需與梯度累積的微步區分。", "lessonId": 39}, {"id": "d5t6", "zh": "迭代", "en": "Iteration", "definition": "演算法循環的一次執行，具體單位依實作而定。", "lessonId": 39}, {"id": "d5t7", "zh": "學習率", "en": "Learning Rate", "definition": "控制梯度更新幅度的係數。", "lessonId": 39}, {"id": "d5t8", "zh": "學習率排程", "en": "Learning Rate Schedule", "definition": "隨訓練步數調整學習率的規則。", "lessonId": 39}, {"id": "d5t9", "zh": "學習率暖身", "en": "Learning Rate Warmup", "definition": "訓練初期逐步提高學習率以改善穩定性。", "lessonId": 39}, {"id": "d5t10", "zh": "梯度下降", "en": "Gradient Descent", "definition": "沿損失梯度的反方向更新參數。", "lessonId": 39}, {"id": "d5t11", "zh": "隨機梯度下降", "en": "Stochastic Gradient Descent, SGD", "definition": "以隨機樣本或小批次估計梯度並更新參數。", "lessonId": 39}, {"id": "d5t12", "zh": "動量", "en": "Momentum", "definition": "累積歷史更新方向以平滑震盪、加快一致方向的移動。", "lessonId": 39}, {"id": "d5t13", "zh": "自適應矩估計", "en": "Adaptive Moment Estimation, Adam", "definition": "使用梯度一階與二階矩估計，自適應調整更新。", "lessonId": 39}, {"id": "d5t14", "zh": "AdamW 最佳化器", "en": "AdamW Optimizer", "definition": "將權重衰減與 Adam 的梯度更新解耦。", "lessonId": 40}, {"id": "d5t15", "zh": "最佳化器", "en": "Optimizer", "definition": "根據梯度與內部狀態決定參數如何更新的演算法。", "lessonId": 40}, {"id": "d5t16", "zh": "損失函數", "en": "Loss Function", "definition": "量化單筆或一批預測與目標差異的函數。", "lessonId": 40}, {"id": "d5t17", "zh": "目標函數", "en": "Objective Function", "definition": "整體要最佳化的量，可包含資料損失與正則化項。", "lessonId": 40}, {"id": "d5t18", "zh": "均方誤差", "en": "Mean Squared Error, MSE", "definition": "預測與真值差值平方的平均，對大誤差較敏感。", "lessonId": 40}, {"id": "d5t19", "zh": "平均絕對誤差", "en": "Mean Absolute Error, MAE", "definition": "預測與真值絕對差值的平均。", "lessonId": 40}, {"id": "d5t20", "zh": "二元交叉熵", "en": "Binary Cross-Entropy, BCE", "definition": "用於二元或多標籤目標的交叉熵損失。", "lessonId": 40}, {"id": "d5t21", "zh": "類別交叉熵", "en": "Categorical Cross-Entropy", "definition": "對互斥類別分布計算的交叉熵損失。", "lessonId": 40}, {"id": "d5t22", "zh": "負對數概似", "en": "Negative Log-Likelihood, NLL", "definition": "對觀測答案機率取負對數；最小化它等價於最大化概似。", "lessonId": 40}, {"id": "d5t23", "zh": "對比損失", "en": "Contrastive Loss", "definition": "讓相似資料的表示更接近、不同資料的表示更可區分。", "lessonId": 40}, {"id": "d5t24", "zh": "正則化", "en": "Regularization", "definition": "加入限制或訓練策略，以抑制過擬合並改善泛化。", "lessonId": 40}, {"id": "d5t25", "zh": "L1 正則化", "en": "L1 Regularization", "definition": "對參數絕對值總和加懲罰，常促進稀疏解。", "lessonId": 40}, {"id": "d5t26", "zh": "L2 正則化", "en": "L2 Regularization", "definition": "對參數平方和加懲罰，抑制過大權重。", "lessonId": 40}, {"id": "d5t27", "zh": "權重衰減", "en": "Weight Decay", "definition": "更新時使權重向零縮小；在自適應最佳化器中不等同一般 L2 懲罰。", "lessonId": 40}, {"id": "d5t28", "zh": "提早停止", "en": "Early Stopping", "definition": "依驗證表現停止訓練，通常還原較佳檢查點。", "lessonId": 41}, {"id": "d5t29", "zh": "梯度裁剪", "en": "Gradient Clipping", "definition": "限制梯度值或範數以改善更新穩定性。", "lessonId": 41}, {"id": "d5t30", "zh": "梯度累積", "en": "Gradient Accumulation", "definition": "累積多個微批次梯度後才更新參數，模擬較大有效批次。", "lessonId": 41}, {"id": "d5t31", "zh": "檢查點", "en": "Checkpoint", "definition": "保存模型、最佳化器及必要訓練狀態以便還原或續訓。", "lessonId": 41}, {"id": "d5t32", "zh": "過擬合", "en": "Overfitting", "definition": "模型過度適應訓練資料，對新資料泛化不佳。", "lessonId": 41}, {"id": "d5t33", "zh": "欠擬合", "en": "Underfitting", "definition": "模型或訓練不足以捕捉資料的重要規律。", "lessonId": 41}, {"id": "d5t34", "zh": "泛化能力", "en": "Generalization", "definition": "模型在未見過且相關的資料上維持表現的能力。", "lessonId": 41}, {"id": "d5t35", "zh": "偏差與變異權衡", "en": "Bias–Variance Tradeoff", "definition": "模型過於簡單與過度敏感於訓練樣本之間的取捨。", "lessonId": 41}, {"id": "d5t36", "zh": "超參數搜尋", "en": "Hyperparameter Search", "definition": "用驗證程序比較不同訓練配置。", "lessonId": 41}, {"id": "d5t37", "zh": "網格搜尋", "en": "Grid Search", "definition": "列舉預先指定的超參數組合。", "lessonId": 41}, {"id": "d5t38", "zh": "隨機搜尋", "en": "Random Search", "definition": "從配置空間隨機抽樣超參數組合。", "lessonId": 41}, {"id": "d5t39", "zh": "貝氏最佳化", "en": "Bayesian Optimization", "definition": "用代理模型與採集策略選擇下一個值得評估的配置。", "lessonId": 41}], "level": "基礎", "prerequisites": [1, 2, 4], "case": "訓練資料 1000 筆、微批次 10 筆，若累積 4 批梯度再更新，忽略邊界處理時每輪有 100 個微批次、25 次參數更新，有效批次為 40。若驗證損失轉差，可檢查過擬合並還原較佳檢查點。", "exercises": ["計算指定資料量、批次與梯度累積下的微步與更新步數。", "在梯度實驗比較學習率，記錄發散與收斂情況。", "制定只使用驗證集的調參計畫，保存模型、最佳化器和隨機狀態。"], "pitfall": "梯度累積不會讓所有訓練行為完全等同真正大批次，例如 BatchNorm 統計可能不同。", "lessonIds": [39, 40, 41], "sourceIds": [2]}, {"id": 6, "title": "評估指標", "en": "Evaluation Metrics", "terms": [{"id": "d6t0", "zh": "混淆矩陣", "en": "Confusion Matrix", "definition": "以真實類別與預測類別交叉計數，觀察錯誤型態。", "lessonId": 42}, {"id": "d6t1", "zh": "真陽性", "en": "True Positive, TP", "definition": "實際為陽性且預測為陽性的案例數。", "lessonId": 42}, {"id": "d6t2", "zh": "真陰性", "en": "True Negative, TN", "definition": "實際為陰性且預測為陰性的案例數。", "lessonId": 42}, {"id": "d6t3", "zh": "假陽性", "en": "False Positive, FP", "definition": "實際為陰性卻預測為陽性的案例數。", "lessonId": 42}, {"id": "d6t4", "zh": "假陰性", "en": "False Negative, FN", "definition": "實際為陽性卻預測為陰性的案例數。", "lessonId": 42}, {"id": "d6t5", "zh": "準確率", "en": "Accuracy", "definition": "所有案例中正確預測的比例，即 (TP+TN)/總數。", "lessonId": 42}, {"id": "d6t6", "zh": "精確率", "en": "Precision", "definition": "預測陽性中實際陽性的比例，即 TP/(TP+FP)。", "lessonId": 42}, {"id": "d6t7", "zh": "召回率／敏感度", "en": "Recall / Sensitivity", "definition": "實際陽性中被找到的比例，即 TP/(TP+FN)。", "lessonId": 42}, {"id": "d6t8", "zh": "特異度", "en": "Specificity", "definition": "實際陰性中正確排除的比例，即 TN/(TN+FP)。", "lessonId": 42}, {"id": "d6t9", "zh": "F1 分數", "en": "F1 Score", "definition": "精確率與召回率的調和平均：2PR/(P+R)。", "lessonId": 43}, {"id": "d6t10", "zh": "ROC 曲線", "en": "Receiver Operating Characteristic Curve", "definition": "改變判定閾值時，真陽性率對假陽性率的曲線。", "lessonId": 43}, {"id": "d6t11", "zh": "ROC 曲線下面積", "en": "Area Under the ROC Curve, ROC-AUC", "definition": "量化跨閾值的排序能力；不直接反映指定閾值的錯誤成本。", "lessonId": 43}, {"id": "d6t12", "zh": "精確率－召回率曲線", "en": "Precision–Recall Curve, PR Curve", "definition": "顯示不同閾值下精確率與召回率的取捨，對罕見陽性常很有用。", "lessonId": 43}, {"id": "d6t13", "zh": "均方根誤差", "en": "Root Mean Squared Error, RMSE", "definition": "MSE 的平方根，單位與目標相同。", "lessonId": 43}, {"id": "d6t14", "zh": "決定係數", "en": "Coefficient of Determination, R²", "definition": "相對於預測平均值基準的平方誤差改善程度，可能為負值。", "lessonId": 43}, {"id": "d6t15", "zh": "交叉驗證", "en": "Cross-Validation", "definition": "多次切分訓練與驗證資料以估計模型表現。", "lessonId": 43}, {"id": "d6t16", "zh": "K 折交叉驗證", "en": "K-Fold Cross-Validation", "definition": "將資料分為 K 份，輪流用一份驗證、其餘訓練。", "lessonId": 43}, {"id": "d6t17", "zh": "基準模型", "en": "Baseline Model", "definition": "用來比較的簡單或既有模型，判斷新方法是否值得。", "lessonId": 43}, {"id": "d6t18", "zh": "基準測試", "en": "Benchmark", "definition": "使用固定任務、資料與規則比較模型或系統。", "lessonId": 44}, {"id": "d6t19", "zh": "消融實驗", "en": "Ablation Study", "definition": "移除或替換系統元件，觀察它對結果的影響。", "lessonId": 44}, {"id": "d6t20", "zh": "錯誤分析", "en": "Error Analysis", "definition": "依類別、來源與情境檢查失敗案例，找出改善方向。", "lessonId": 44}, {"id": "d6t21", "zh": "機率校準", "en": "Probability Calibration", "definition": "檢查預測機率是否與實際發生比例相符。", "lessonId": 44}, {"id": "d6t22", "zh": "困惑度", "en": "Perplexity", "definition": "常定義為平均負對數概似的指數，跨不同分詞器比較需謹慎。", "lessonId": 44}, {"id": "d6t23", "zh": "人工評估", "en": "Human Evaluation", "definition": "由人依明確準則判斷正確性、實用性或偏好。", "lessonId": 44}, {"id": "d6t24", "zh": "評估資料污染", "en": "Evaluation Data Contamination", "definition": "訓練資料包含評估題目或其近似內容，使評估偏樂觀。", "lessonId": 44}], "level": "基礎", "prerequisites": [1, 3], "case": "故障偵測有 TP=8、FP=2、FN=12、TN=78，準確率是 86%，精確率是 80%，召回率只有 40%。若漏報成本很高，不能只依準確率選模型；還要比較閾值與成本。", "exercises": ["手算混淆矩陣的 Precision、Recall、Specificity 與 F1。", "為不平衡資料選擇 ROC 或 PR 圖並解釋理由。", "建立基準、消融及人工評估表，檢查測試集污染與校準。"], "pitfall": "高準確率不保證找到罕見陽性；低困惑度不代表所有回答都真實。", "lessonIds": [42, 43, 44], "sourceIds": [0, 1]}, {"id": 7, "title": "電腦視覺", "en": "Computer Vision", "terms": [{"id": "d7t0", "zh": "電腦視覺", "en": "Computer Vision, CV", "definition": "讓系統理解影像與影片內容的研究領域。", "lessonId": 45}, {"id": "d7t1", "zh": "影像分類", "en": "Image Classification", "definition": "為整張影像預測一個或多個類別。", "lessonId": 45}, {"id": "d7t2", "zh": "物件偵測", "en": "Object Detection", "definition": "找出物件位置並判定其類別，常輸出邊界框。", "lessonId": 45}, {"id": "d7t3", "zh": "語意分割", "en": "Semantic Segmentation", "definition": "為每個像素指定語意類別，不區分同類別的不同個體。", "lessonId": 45}, {"id": "d7t4", "zh": "實例分割", "en": "Instance Segmentation", "definition": "為各物件實例分別產生像素遮罩。", "lessonId": 45}, {"id": "d7t5", "zh": "全景分割", "en": "Panoptic Segmentation", "definition": "結合可數物件的實例分割與背景類別的語意分割。", "lessonId": 45}, {"id": "d7t6", "zh": "姿態估計", "en": "Pose Estimation", "definition": "預測人體或物體的關鍵點及姿態。", "lessonId": 45}, {"id": "d7t7", "zh": "光學字元辨識", "en": "Optical Character Recognition, OCR", "definition": "從影像中辨識並轉錄文字。", "lessonId": 45}, {"id": "d7t8", "zh": "人臉辨識", "en": "Face Recognition", "definition": "用人臉特徵驗證或辨別身分，涉及生物辨識資料。", "lessonId": 45}, {"id": "d7t9", "zh": "物件追蹤", "en": "Object Tracking", "definition": "在影片不同影格之間維持物件身分與位置對應。", "lessonId": 45}, {"id": "d7t10", "zh": "卷積神經網路", "en": "Convolutional Neural Network, CNN", "definition": "利用局部連接與共享卷積核學習空間模式的網路。", "lessonId": 45}, {"id": "d7t11", "zh": "卷積", "en": "Convolution", "definition": "以卷積核掃過輸入計算局部加權和；深度學習實作常採互相關形式。", "lessonId": 46}, {"id": "d7t12", "zh": "卷積核", "en": "Kernel", "definition": "卷積運算中使用的一組局部權重。", "lessonId": 46}, {"id": "d7t13", "zh": "濾波器", "en": "Filter", "definition": "影像網路中用於產生某個輸出通道的可學習運算核。", "lessonId": 46}, {"id": "d7t14", "zh": "特徵圖", "en": "Feature Map", "definition": "網路某層的空間激活表示。", "lessonId": 46}, {"id": "d7t15", "zh": "通道", "en": "Channel", "definition": "表示影像色彩或中間特徵種類的軸。", "lessonId": 46}, {"id": "d7t16", "zh": "步幅", "en": "Stride", "definition": "卷積或池化視窗每次移動的距離。", "lessonId": 46}, {"id": "d7t17", "zh": "填補", "en": "Padding", "definition": "在輸入邊界補值，以控制輸出大小或邊界處理。", "lessonId": 46}, {"id": "d7t18", "zh": "感受野", "en": "Receptive Field", "definition": "某個輸出位置所能受影響的原始輸入範圍。", "lessonId": 46}, {"id": "d7t19", "zh": "池化", "en": "Pooling", "definition": "在局部區域聚合數值，常降低空間尺寸。", "lessonId": 46}, {"id": "d7t20", "zh": "最大池化", "en": "Max Pooling", "definition": "以視窗內最大值作為聚合結果。", "lessonId": 46}, {"id": "d7t21", "zh": "平均池化", "en": "Average Pooling", "definition": "以視窗內平均值作為聚合結果。", "lessonId": 46}, {"id": "d7t22", "zh": "全域平均池化", "en": "Global Average Pooling", "definition": "對每個通道的全部空間位置取平均。", "lessonId": 47}, {"id": "d7t23", "zh": "展平", "en": "Flatten", "definition": "重新排列張量形狀，把多個軸合併，不會自行學習參數。", "lessonId": 47}, {"id": "d7t24", "zh": "上採樣", "en": "Upsampling", "definition": "提高空間或時間取樣密度，不保證增加真實細節。", "lessonId": 47}, {"id": "d7t25", "zh": "下採樣", "en": "Downsampling", "definition": "降低空間或時間取樣密度。", "lessonId": 47}, {"id": "d7t26", "zh": "轉置卷積", "en": "Transposed Convolution", "definition": "與卷積線性算子的轉置相對應，常用於可學習的上採樣，並非卷積的真正反運算。", "lessonId": 47}, {"id": "d7t27", "zh": "視覺 Transformer", "en": "Vision Transformer, ViT", "definition": "將影像區塊表示成序列，以 Transformer 處理影像。", "lessonId": 47}, {"id": "d7t28", "zh": "交並比", "en": "Intersection over Union, IoU", "definition": "兩個區域交集面積除以聯集面積。", "lessonId": 47}, {"id": "d7t29", "zh": "非極大值抑制", "en": "Non-Maximum Suppression, NMS", "definition": "依分數與重疊程度移除重複偵測框。", "lessonId": 47}, {"id": "d7t30", "zh": "超解析度", "en": "Super-Resolution", "definition": "由低解析度資料估計較高解析度結果，生成細節未必是真實細節。", "lessonId": 47}, {"id": "d7t31", "zh": "深度估計", "en": "Depth Estimation", "definition": "預測場景各位置到相機的距離或相對深度。", "lessonId": 47}, {"id": "d7t32", "zh": "光流", "en": "Optical Flow", "definition": "估計連續影格之間像素的表觀位移。", "lessonId": 47}], "level": "進階", "prerequisites": [4, 5], "case": "28×28×1 影像通過 16 個 3×3、stride=1、padding=0 卷積核，輸出為 26×26×16。再以 2×2 池化得到 13×13×16，展平為 2704。偵測需框線標籤，實例分割則需每個物件的遮罩。", "exercises": ["手算卷積、池化、展平的輸出形狀與感受野變化。", "為同一街景分別定義分類、偵測、語意分割與實例分割標籤。", "比較重疊框的 IoU 與 NMS；說明超解析生成細節的可信範圍。"], "pitfall": "轉置卷積不是一般卷積的反函數；上採樣不等於恢復真實細節。", "lessonIds": [45, 46, 47], "sourceIds": [2]}, {"id": 8, "title": "自然語言處理與序列模型", "en": "NLP & Sequence Models", "terms": [{"id": "d8t0", "zh": "自然語言處理", "en": "Natural Language Processing, NLP", "definition": "以計算方法處理與分析人類語言。", "lessonId": 48}, {"id": "d8t1", "zh": "自然語言理解", "en": "Natural Language Understanding, NLU", "definition": "理解文字的意圖、語意或結構。", "lessonId": 48}, {"id": "d8t2", "zh": "自然語言生成", "en": "Natural Language Generation, NLG", "definition": "把資料或內部表示轉成自然語言。", "lessonId": 48}, {"id": "d8t3", "zh": "詞元", "en": "Token", "definition": "分詞器輸出的基本處理單位，不一定等於一個單字。", "lessonId": 48}, {"id": "d8t4", "zh": "分詞", "en": "Tokenization", "definition": "將文字轉為詞元序列的過程。", "lessonId": 48}, {"id": "d8t5", "zh": "分詞器", "en": "Tokenizer", "definition": "定義文字與詞元編號轉換規則的元件。", "lessonId": 48}, {"id": "d8t6", "zh": "子詞", "en": "Subword", "definition": "介於字元與完整單字之間的文字片段。", "lessonId": 48}, {"id": "d8t7", "zh": "位元組對編碼", "en": "Byte Pair Encoding, BPE", "definition": "反覆合併常見相鄰單位以建立子詞詞彙表的方法。", "lessonId": 48}, {"id": "d8t8", "zh": "詞彙表", "en": "Vocabulary", "definition": "分詞器可表示的詞元及其編號集合。", "lessonId": 48}, {"id": "d8t9", "zh": "詞嵌入", "en": "Word Embedding", "definition": "以向量表示詞語，傳統靜態詞嵌入通常每詞一個向量。", "lessonId": 49}, {"id": "d8t10", "zh": "句子嵌入", "en": "Sentence Embedding", "definition": "將整句或片段映射到向量，用於相似度與檢索。", "lessonId": 49}, {"id": "d8t11", "zh": "上下文嵌入", "en": "Contextual Embedding", "definition": "同一詞語的表示依周圍內容改變。", "lessonId": 49}, {"id": "d8t12", "zh": "語言模型", "en": "Language Model", "definition": "估計文字序列或下一詞元的機率模型。", "lessonId": 49}, {"id": "d8t13", "zh": "循環神經網路", "en": "Recurrent Neural Network, RNN", "definition": "透過循環狀態依序處理輸入的神經網路。", "lessonId": 49}, {"id": "d8t14", "zh": "長短期記憶網路", "en": "Long Short-Term Memory, LSTM", "definition": "以記憶狀態及閘門改善長距離序列學習的 RNN 變體。", "lessonId": 49}, {"id": "d8t15", "zh": "閘控循環單元", "en": "Gated Recurrent Unit, GRU", "definition": "以更新與重設閘門控制狀態的循環單元。", "lessonId": 49}, {"id": "d8t16", "zh": "序列到序列模型", "en": "Sequence-to-Sequence Model, Seq2Seq", "definition": "將一個序列轉成另一個序列，例如翻譯。", "lessonId": 49}, {"id": "d8t17", "zh": "編碼器", "en": "Encoder", "definition": "把輸入轉成可供後續處理的表示。", "lessonId": 49}, {"id": "d8t18", "zh": "解碼器", "en": "Decoder", "definition": "依條件表示產生或重建輸出。", "lessonId": 50}, {"id": "d8t19", "zh": "機器翻譯", "en": "Machine Translation", "definition": "自動將文字從一種語言轉成另一種語言。", "lessonId": 50}, {"id": "d8t20", "zh": "情感分析", "en": "Sentiment Analysis", "definition": "判定文字中的情感傾向，例如正面或負面。", "lessonId": 50}, {"id": "d8t21", "zh": "命名實體辨識", "en": "Named Entity Recognition, NER", "definition": "辨識人名、地名、組織等實體片段。", "lessonId": 50}, {"id": "d8t22", "zh": "問答系統", "en": "Question Answering, QA", "definition": "依問題與可用資訊產生或擷取答案。", "lessonId": 50}, {"id": "d8t23", "zh": "文本摘要", "en": "Text Summarization", "definition": "保留主要資訊並縮短文本，可採擷取式或生成式方法。", "lessonId": 50}, {"id": "d8t24", "zh": "語音辨識", "en": "Automatic Speech Recognition, ASR", "definition": "將語音訊號辨識為文字序列。", "lessonId": 50}, {"id": "d8t25", "zh": "文字轉語音", "en": "Text-to-Speech, TTS", "definition": "依文字生成語音，可用於文章朗讀、導航或對話回覆。", "lessonId": 50}, {"id": "d8t26", "zh": "語音轉文字", "en": "Speech-to-Text, STT", "definition": "將語音轉錄成文字，與 ASR 的應用範圍高度重疊。", "lessonId": 50}], "level": "進階", "prerequisites": [4], "case": "把客服語音轉成文字，再做情感分析、實體辨識與摘要。ASR 與 STT 描述的任務高度重疊；Tokenizer 決定模型看到的單位，Embedding 決定每個單位的向量表示，兩者角色不同。", "exercises": ["為一段中英混合文字描述可能的詞元與子詞切分，不假設一字必是一詞元。", "畫出 Encoder–Decoder 或 RNN 處理序列的資料流。", "設計語音轉錄到摘要的評估，區分轉錄錯誤與摘要錯誤。"], "pitfall": "詞彙表大小不等於嵌入維度；ASR、STT 常是同一轉錄任務的不同名稱。", "lessonIds": [48, 49, 50], "sourceIds": [3, 0]}, {"id": 9, "title": "Transformer 與注意力機制", "en": "Transformer & Attention", "terms": [{"id": "d9t0", "zh": "Transformer 架構", "en": "Transformer", "definition": "以注意力及前饋網路等元件處理序列的模型架構。", "lessonId": 51}, {"id": "d9t1", "zh": "注意力機制", "en": "Attention Mechanism", "definition": "依相關程度加權聚合資訊的機制。", "lessonId": 51}, {"id": "d9t2", "zh": "自注意力", "en": "Self-Attention", "definition": "查詢、鍵和值來自同一序列的注意力運算。", "lessonId": 51}, {"id": "d9t3", "zh": "交叉注意力", "en": "Cross-Attention", "definition": "查詢來自一組表示，鍵和值來自另一組表示。", "lessonId": 51}, {"id": "d9t4", "zh": "多頭注意力", "en": "Multi-Head Attention, MHA", "definition": "以多組投影並行學習不同的注意力關係。", "lessonId": 51}, {"id": "d9t5", "zh": "注意力頭", "en": "Attention Head", "definition": "多頭注意力中一組查詢、鍵、值投影與聚合單元。", "lessonId": 51}, {"id": "d9t6", "zh": "查詢向量", "en": "Query, Q", "definition": "表示某個位置正在尋找什麼資訊的投影向量。", "lessonId": 51}, {"id": "d9t7", "zh": "鍵向量", "en": "Key, K", "definition": "供查詢計算匹配程度的投影向量。", "lessonId": 51}, {"id": "d9t8", "zh": "值向量", "en": "Value, V", "definition": "依注意力權重被聚合的資訊向量。", "lessonId": 51}, {"id": "d9t9", "zh": "縮放點積注意力", "en": "Scaled Dot-Product Attention", "definition": "常用公式為 softmax(QKᵀ/√dₖ)V，可搭配遮罩。", "lessonId": 52}, {"id": "d9t10", "zh": "注意力矩陣", "en": "Attention Matrix", "definition": "表示各查詢位置對鍵位置權重的矩陣。", "lessonId": 52}, {"id": "d9t11", "zh": "注意力遮罩", "en": "Attention Mask", "definition": "限制某些位置參與注意力計算，例如忽略填補詞元。", "lessonId": 52}, {"id": "d9t12", "zh": "因果遮罩", "en": "Causal Mask", "definition": "禁止當前位置看到未來位置，用於自回歸生成。", "lessonId": 52}, {"id": "d9t13", "zh": "位置編碼", "en": "Positional Encoding", "definition": "將序列順序資訊加入表示的方式。", "lessonId": 52}, {"id": "d9t14", "zh": "位置嵌入", "en": "Positional Embedding", "definition": "以向量表示位置資訊，常指可學習的位置向量。", "lessonId": 52}, {"id": "d9t15", "zh": "旋轉位置嵌入", "en": "Rotary Position Embedding, RoPE", "definition": "依位置旋轉查詢與鍵的分量，以編入相對位置關係。", "lessonId": 52}, {"id": "d9t16", "zh": "前饋網路", "en": "Feed-Forward Network, FFN", "definition": "對各位置的表示進行非線性轉換的子網路。", "lessonId": 52}, {"id": "d9t17", "zh": "上下文", "en": "Context", "definition": "模型在當次任務可使用的文字、資料及互動資訊。", "lessonId": 52}, {"id": "d9t18", "zh": "上下文視窗", "en": "Context Window", "definition": "模型單次可處理的序列範圍，不代表長期記憶。", "lessonId": 53}, {"id": "d9t19", "zh": "序列長度", "en": "Sequence Length", "definition": "序列所含詞元或時間步的數量。", "lessonId": 53}, {"id": "d9t20", "zh": "鍵值快取", "en": "Key-Value Cache, KV Cache", "definition": "保存已計算的鍵與值，減少自回歸生成的重複運算。", "lessonId": 53}, {"id": "d9t21", "zh": "分組查詢注意力", "en": "Grouped-Query Attention, GQA", "definition": "多個查詢頭共享一組鍵和值頭，降低快取成本。", "lessonId": 53}, {"id": "d9t22", "zh": "多查詢注意力", "en": "Multi-Query Attention, MQA", "definition": "所有查詢頭共享一組鍵和值頭的注意力方式。", "lessonId": 53}, {"id": "d9t23", "zh": "稀疏注意力", "en": "Sparse Attention", "definition": "只讓部分位置配對參與注意力，以降低運算或記憶體需求。", "lessonId": 53}, {"id": "d9t24", "zh": "滑動視窗注意力", "en": "Sliding-Window Attention", "definition": "各位置主要參考鄰近固定視窗內的位置。", "lessonId": 53}, {"id": "d9t25", "zh": "混合專家模型", "en": "Mixture of Experts, MoE", "definition": "以路由器選擇部分專家子網路處理輸入，總參數不等於每次激活參數。", "lessonId": 53}, {"id": "d9t26", "zh": "路由器", "en": "Router", "definition": "決定輸入交給哪些專家或處理路徑的元件。", "lessonId": 53}], "level": "進階", "prerequisites": [2, 4, 8], "case": "對長度 N 的序列，標準全注意力每頭有 N×N 個查詢與鍵的配對，N 翻倍配對量變四倍。自回歸生成使用因果遮罩防止看未來；KV Cache 保存已算的鍵值，GQA 讓多個查詢頭共享鍵值頭。", "exercises": ["手算 Q、K、V 的小矩陣並說明 softmax 權重。", "用實驗室比較不同 N 的注意力矩陣規模，區分理論矩陣與實際引擎記憶體。", "比較 MHA、GQA、MQA、滑動視窗及 MoE 各自節省的資源。"], "pitfall": "長上下文不等於長期記憶；MoE 的總參數量不等於每詞元激活參數量。", "lessonIds": [51, 52, 53], "sourceIds": [3, 0]}, {"id": 10, "title": "大型語言模型與文字生成", "en": "LLMs & Text Generation", "terms": [{"id": "d10t0", "zh": "大型語言模型", "en": "Large Language Model, LLM", "definition": "在大量語言資料上訓練、具有大量參數的語言模型，沒有唯一規模門檻。", "lessonId": 54}, {"id": "d10t1", "zh": "小型語言模型", "en": "Small Language Model, SLM", "definition": "相對較小、通常較適合受限資源的語言模型。", "lessonId": 54}, {"id": "d10t2", "zh": "基礎模型", "en": "Foundation Model", "definition": "以廣泛資料訓練並可適應多種下游任務的模型。", "lessonId": 54}, {"id": "d10t3", "zh": "預訓練", "en": "Pretraining", "definition": "先以通用目標學習廣泛表示與規律的訓練階段。", "lessonId": 54}, {"id": "d10t4", "zh": "持續預訓練", "en": "Continued Pretraining", "definition": "在既有模型上繼續預訓練，例如加入領域資料。", "lessonId": 54}, {"id": "d10t5", "zh": "後訓練", "en": "Post-Training", "definition": "預訓練後改善指令遵循、偏好或任務能力的訓練程序。", "lessonId": 54}, {"id": "d10t6", "zh": "指令微調", "en": "Instruction Tuning", "definition": "使用指令與回覆樣本學習遵循任務要求。", "lessonId": 54}, {"id": "d10t7", "zh": "監督式微調", "en": "Supervised Fine-Tuning, SFT", "definition": "以帶有目標輸出的資料微調模型參數。", "lessonId": 54}, {"id": "d10t8", "zh": "偏好對齊", "en": "Preference Alignment", "definition": "利用偏好訊號調整模型的輸出行為。", "lessonId": 54}, {"id": "d10t9", "zh": "自回歸生成", "en": "Autoregressive Generation", "definition": "依已有輸出逐步預測下一單位的生成方式。", "lessonId": 54}, {"id": "d10t10", "zh": "下一詞元預測", "en": "Next-Token Prediction", "definition": "依前文預測下一個詞元，是許多語言模型的訓練目標。", "lessonId": 54}, {"id": "d10t11", "zh": "遮罩語言建模", "en": "Masked Language Modeling, MLM", "definition": "遮住部分文字並要求模型預測被遮住的內容。", "lessonId": 55}, {"id": "d10t12", "zh": "提示詞", "en": "Prompt", "definition": "提供給模型的任務指令、背景與輸入內容。", "lessonId": 55}, {"id": "d10t13", "zh": "提示工程", "en": "Prompt Engineering", "definition": "設計、測試與改進提示內容與格式的過程。", "lessonId": 55}, {"id": "d10t14", "zh": "系統提示詞", "en": "System Prompt", "definition": "應用提供的高層行為指引，具體優先級取決於系統設計。", "lessonId": 55}, {"id": "d10t15", "zh": "少樣本提示", "en": "Few-Shot Prompting", "definition": "在提示中提供少數範例，不必更新模型權重。", "lessonId": 55}, {"id": "d10t16", "zh": "上下文學習", "en": "In-Context Learning, ICL", "definition": "模型依當次上下文中的示例或資訊調整輸出，不等於參數訓練。", "lessonId": 55}, {"id": "d10t17", "zh": "思維鏈", "en": "Chain of Thought, CoT", "definition": "以中間推理步驟幫助處理複雜任務的方法；生成步驟不保證忠實或正確。", "lessonId": 55}, {"id": "d10t18", "zh": "檢索式提示", "en": "Retrieval-Based Prompting", "definition": "把檢索到的相關資訊加入提示中。", "lessonId": 55}, {"id": "d10t19", "zh": "結構化輸出", "en": "Structured Output", "definition": "依指定結構產生結果，例如符合欄位要求的 JSON。", "lessonId": 55}, {"id": "d10t20", "zh": "受限解碼", "en": "Constrained Decoding", "definition": "在解碼時限制允許的詞元或語法，以符合格式或規則。", "lessonId": 55}, {"id": "d10t21", "zh": "貪婪解碼", "en": "Greedy Decoding", "definition": "每一步選取機率最大的詞元，不保證整體序列最優。", "lessonId": 55}, {"id": "d10t22", "zh": "束搜尋", "en": "Beam Search", "definition": "保留多條高分候選序列並逐步擴展。", "lessonId": 56}, {"id": "d10t23", "zh": "取樣", "en": "Sampling", "definition": "依機率分布隨機抽取輸出詞元或樣本。", "lessonId": 56}, {"id": "d10t24", "zh": "溫度", "en": "Temperature", "definition": "調整 logits 尺度以改變分布集中程度，不是正確性保證。", "lessonId": 56}, {"id": "d10t25", "zh": "Top-k 取樣", "en": "Top-k Sampling", "definition": "只在機率最高的 k 個詞元中重新正規化並取樣。", "lessonId": 56}, {"id": "d10t26", "zh": "核取樣", "en": "Nucleus Sampling / Top-p Sampling", "definition": "在累積機率達到 p 的候選集合內取樣。", "lessonId": 56}, {"id": "d10t27", "zh": "重複懲罰", "en": "Repetition Penalty", "definition": "調整已出現詞元的分數以控制重複，具體公式依引擎而異。", "lessonId": 56}, {"id": "d10t28", "zh": "停止序列", "en": "Stop Sequence", "definition": "生成遇到指定序列時終止輸出。", "lessonId": 56}, {"id": "d10t29", "zh": "串流輸出", "en": "Streaming Output", "definition": "在完整結果完成前逐段傳回輸出。", "lessonId": 56}, {"id": "d10t30", "zh": "幻覺", "en": "Hallucination", "definition": "生成看似合理但與事實或指定來源不符的內容。", "lessonId": 56}, {"id": "d10t31", "zh": "知識截止時間", "en": "Knowledge Cutoff", "definition": "模型訓練所涵蓋資料時期的概略界線，不保證此前所有事實都知道。", "lessonId": 56}, {"id": "d10t32", "zh": "推論時計算", "en": "Test-Time Compute / Inference-Time Compute", "definition": "在推論階段投入額外搜尋、檢查或推理運算以改善結果。", "lessonId": 56}], "level": "進階", "prerequisites": [8, 9], "case": "為會議摘要設計系統指引、輸出 JSON 欄位與兩個範例。範例放在上下文中屬於 ICL；若更新模型參數才是微調。把 temperature 調低可能更集中，但仍需要檢查數字、來源與 JSON 是否符合結構。", "exercises": ["區分預訓練、SFT、偏好對齊的資料與目標。", "比較 greedy、beam、top-k、top-p 對候選序列的影響。", "設計結構驗證與事實檢查，記錄幻覺、延遲及不同推論預算的品質。"], "pitfall": "格式正確不等於內容正確；輸出的推理步驟也不保證忠實。", "lessonIds": [54, 55, 56], "sourceIds": [3, 0]}, {"id": 11, "title": "RAG 與知識檢索", "en": "RAG & Retrieval", "terms": [{"id": "d11t0", "zh": "檢索增強生成", "en": "Retrieval-Augmented Generation, RAG", "definition": "先檢索相關資料，再提供給生成模型作為回答依據。", "lessonId": 57}, {"id": "d11t1", "zh": "資訊檢索", "en": "Information Retrieval, IR", "definition": "從集合中找出與查詢相關的文件或片段。", "lessonId": 57}, {"id": "d11t2", "zh": "文件解析", "en": "Document Parsing", "definition": "把 PDF、網頁等文件轉成文字、結構與中繼資料。", "lessonId": 57}, {"id": "d11t3", "zh": "文件切塊", "en": "Document Chunking", "definition": "把長文件分成適合索引與檢索的片段。", "lessonId": 57}, {"id": "d11t4", "zh": "區塊大小", "en": "Chunk Size", "definition": "每個片段的長度，常以詞元數或字元數計算。", "lessonId": 57}, {"id": "d11t5", "zh": "區塊重疊", "en": "Chunk Overlap", "definition": "相鄰片段共享的內容量，用於保留邊界語境。", "lessonId": 57}, {"id": "d11t6", "zh": "嵌入模型", "en": "Embedding Model", "definition": "把文字或其他資料映射到可比較的向量空間。", "lessonId": 57}, {"id": "d11t7", "zh": "向量資料庫", "en": "Vector Database", "definition": "儲存向量、中繼資料並提供相似度查詢的系統。", "lessonId": 57}, {"id": "d11t8", "zh": "向量索引", "en": "Vector Index", "definition": "加速向量搜尋的資料結構。", "lessonId": 57}, {"id": "d11t9", "zh": "向量搜尋", "en": "Vector Search", "definition": "依向量距離或相似度尋找候選資料。", "lessonId": 57}, {"id": "d11t10", "zh": "語意搜尋", "en": "Semantic Search", "definition": "以意義相近程度檢索內容，不限於字面相同。", "lessonId": 58}, {"id": "d11t11", "zh": "關鍵字搜尋", "en": "Keyword Search", "definition": "依文字詞項、匹配與統計權重檢索內容。", "lessonId": 58}, {"id": "d11t12", "zh": "混合搜尋", "en": "Hybrid Search", "definition": "結合關鍵字與向量等不同檢索訊號。", "lessonId": 58}, {"id": "d11t13", "zh": "稠密檢索", "en": "Dense Retrieval", "definition": "使用多數分量非零的向量表示進行檢索。", "lessonId": 58}, {"id": "d11t14", "zh": "稀疏檢索", "en": "Sparse Retrieval", "definition": "使用大量零分量的詞項或學習表示檢索，例如 BM25 類方法。", "lessonId": 58}, {"id": "d11t15", "zh": "近似最近鄰搜尋", "en": "Approximate Nearest Neighbor Search, ANN Search", "definition": "用可接受的召回損失換取更快的最近鄰查詢；ANN 此處不是神經網路。", "lessonId": 58}, {"id": "d11t16", "zh": "餘弦相似度", "en": "Cosine Similarity", "definition": "點積除以兩向量範數乘積，衡量方向相近程度。", "lessonId": 58}, {"id": "d11t17", "zh": "歐幾里得距離", "en": "Euclidean Distance", "definition": "兩點差向量的 L2 長度。", "lessonId": 58}, {"id": "d11t18", "zh": "重新排序", "en": "Reranking", "definition": "以較精細的模型對第一階段檢索候選再評分。", "lessonId": 58}, {"id": "d11t19", "zh": "重新排序模型", "en": "Reranker", "definition": "同時考慮查詢與候選內容，估計相關程度的模型。", "lessonId": 58}, {"id": "d11t20", "zh": "查詢改寫", "en": "Query Rewriting", "definition": "把原始問題改成更適合檢索的表達。", "lessonId": 59}, {"id": "d11t21", "zh": "查詢擴展", "en": "Query Expansion", "definition": "增加同義詞或相關條件以改善檢索涵蓋。", "lessonId": 59}, {"id": "d11t22", "zh": "中繼資料篩選", "en": "Metadata Filtering", "definition": "依日期、來源、使用者權限等條件限制候選集合。", "lessonId": 59}, {"id": "d11t23", "zh": "上下文壓縮", "en": "Context Compression", "definition": "保留與問題相關的資訊以減少送入模型的內容量。", "lessonId": 59}, {"id": "d11t24", "zh": "來源引用", "en": "Source Citation", "definition": "把回答中的說法對應到可查證的原始資料位置。", "lessonId": 59}, {"id": "d11t25", "zh": "依據來源生成", "en": "Grounded Generation", "definition": "要求輸出以所提供的來源證據為依據。", "lessonId": 59}, {"id": "d11t26", "zh": "答案忠實度", "en": "Answer Faithfulness", "definition": "回答是否受提供的上下文支持，不等同外部世界的全面正確性。", "lessonId": 59}, {"id": "d11t27", "zh": "知識圖譜", "en": "Knowledge Graph", "definition": "以實體與關係組成圖狀結構表示知識。", "lessonId": 59}, {"id": "d11t28", "zh": "圖譜式 RAG", "en": "Graph-Based RAG", "definition": "利用圖關係進行檢索、聚合或輔助生成的 RAG 方法。", "lessonId": 59}], "level": "進階", "prerequisites": [8, 10], "case": "公司文件問答先解析手冊、依段落切塊，建立文字與向量索引。查詢先做權限篩選，再混合檢索、重新排序，回傳帶段落引用的答案。對無證據題，保留明確回答資料不足的路徑。", "exercises": ["以同一手冊比較兩種 chunk size 與 overlap，記錄被切斷的資訊。", "設計關鍵字、向量與混合檢索對照，檢查近似搜尋的召回與速度。", "建立有答案、無答案、權限受限三類測試，分別評估檢索、忠實度及引用。"], "pitfall": "RAG 不更新模型權重也能加入新資料，但不能保證消除幻覺或自動處理權限。", "lessonIds": [57, 58, 59], "sourceIds": [3, 0]}, {"id": 12, "title": "微調與模型壓縮", "en": "Fine-Tuning & Compression", "terms": [{"id": "d12t0", "zh": "微調", "en": "Fine-Tuning", "definition": "在預訓練模型上，用新資料繼續更新部分或全部參數。", "lessonId": 60}, {"id": "d12t1", "zh": "全參數微調", "en": "Full Fine-Tuning", "definition": "對模型所有可訓練參數進行更新。", "lessonId": 60}, {"id": "d12t2", "zh": "參數高效微調", "en": "Parameter-Efficient Fine-Tuning, PEFT", "definition": "只訓練少量額外或選定參數，以降低訓練與儲存成本。", "lessonId": 60}, {"id": "d12t3", "zh": "低秩適應", "en": "Low-Rank Adaptation, LoRA", "definition": "以低秩矩陣乘積表示權重更新，通常凍結原模型權重。", "lessonId": 60}, {"id": "d12t4", "zh": "量化低秩適應", "en": "Quantized Low-Rank Adaptation, QLoRA", "definition": "在量化的凍結基礎模型上訓練 LoRA 等適配參數。", "lessonId": 60}, {"id": "d12t5", "zh": "適配器", "en": "Adapter", "definition": "插入或附加到既有模型、供任務適應的小型可訓練模組。", "lessonId": 60}, {"id": "d12t6", "zh": "前綴微調", "en": "Prefix Tuning", "definition": "學習加入注意力相關表示的連續前綴參數。", "lessonId": 60}, {"id": "d12t7", "zh": "軟提示微調", "en": "Prompt Tuning", "definition": "學習輸入端的連續提示向量，而非手寫離散文字。", "lessonId": 60}, {"id": "d12t8", "zh": "凍結參數", "en": "Parameter Freezing", "definition": "訓練時保持指定參數不更新。", "lessonId": 60}, {"id": "d12t9", "zh": "模型合併", "en": "Model Merging", "definition": "以某種規則組合模型或權重更新，不保證所有能力都能保留。", "lessonId": 61}, {"id": "d12t10", "zh": "災難性遺忘", "en": "Catastrophic Forgetting", "definition": "學習新任務後，原有任務能力大幅下降。", "lessonId": 61}, {"id": "d12t11", "zh": "知識蒸餾", "en": "Knowledge Distillation", "definition": "利用教師模型的輸出或中間表示訓練學生模型。", "lessonId": 61}, {"id": "d12t12", "zh": "教師模型", "en": "Teacher Model", "definition": "在蒸餾中提供學習訊號的模型。", "lessonId": 61}, {"id": "d12t13", "zh": "學生模型", "en": "Student Model", "definition": "在蒸餾中學習教師行為的模型，常較小但不必然。", "lessonId": 61}, {"id": "d12t14", "zh": "量化", "en": "Quantization", "definition": "以較低精度或較少可表示數值儲存或計算模型數值。", "lessonId": 61}, {"id": "d12t15", "zh": "訓練後量化", "en": "Post-Training Quantization, PTQ", "definition": "訓練完成後量化模型，可能需要代表性資料校準。", "lessonId": 61}, {"id": "d12t16", "zh": "量化感知訓練", "en": "Quantization-Aware Training, QAT", "definition": "訓練時模擬量化效果，使模型適應低精度誤差。", "lessonId": 61}, {"id": "d12t17", "zh": "剪枝", "en": "Pruning", "definition": "移除或屏蔽部分參數、通道或其他結構。", "lessonId": 61}, {"id": "d12t18", "zh": "結構化剪枝", "en": "Structured Pruning", "definition": "移除完整通道、頭或網路層，較容易配合一般硬體加速。", "lessonId": 62}, {"id": "d12t19", "zh": "非結構化剪枝", "en": "Unstructured Pruning", "definition": "移除個別權重，實際加速常需要稀疏運算支援。", "lessonId": 62}, {"id": "d12t20", "zh": "稀疏性", "en": "Sparsity", "definition": "表示大量數值為零或大量路徑未被使用的特性。", "lessonId": 62}, {"id": "d12t21", "zh": "混合精度", "en": "Mixed Precision", "definition": "在不同運算使用不同精度，以平衡速度、記憶體與穩定性。", "lessonId": 62}, {"id": "d12t22", "zh": "半精度浮點數", "en": "FP16", "definition": "16 位元浮點格式，動態範圍與有效精度有限。", "lessonId": 62}, {"id": "d12t23", "zh": "腦浮點數格式", "en": "Brain Floating Point, BF16", "definition": "16 位元格式，指數範圍較接近 FP32，但尾數精度較低。", "lessonId": 62}, {"id": "d12t24", "zh": "八位元浮點數", "en": "FP8", "definition": "一類 8 位元浮點格式，具體範圍與精度依格式而異。", "lessonId": 62}, {"id": "d12t25", "zh": "八位元整數", "en": "INT8", "definition": "8 位元整數表示，量化時通常搭配比例與零點等資訊。", "lessonId": 62}, {"id": "d12t26", "zh": "四位元整數", "en": "INT4", "definition": "4 位元整數表示，可大幅壓縮權重，但需要相容的量化運算。", "lessonId": 62}], "level": "進階", "prerequisites": [5, 10], "case": "在受限 GPU 上做領域適應，可凍結基礎權重並訓練 LoRA；QLoRA 再用量化基礎模型降低記憶體。部署前比較品質、峰值記憶體與延遲，不能因檔案更小就直接宣稱更快。", "exercises": ["區分 Full Fine-Tuning、LoRA、Prefix Tuning 與 Prompt Tuning 更新哪些參數。", "比較 PTQ、QAT、蒸餾與剪枝，需要哪些資料及硬體支援。", "列出 FP16、BF16、FP8、INT8、INT4 的取捨並設計遺忘測試。"], "pitfall": "量化不保證在所有硬體加速；合併模型也不保證保留所有能力。", "lessonIds": [60, 61, 62], "sourceIds": [3, 0]}, {"id": 13, "title": "影像、影片與音訊生成", "en": "Image, Video & Audio Generation", "terms": [{"id": "d13t0", "zh": "多模態", "en": "Multimodality", "definition": "同時涉及文字、影像、音訊或動作等不同資料形式。", "lessonId": 63}, {"id": "d13t1", "zh": "多模態模型", "en": "Multimodal Model", "definition": "能處理或生成多種模態資料的模型。", "lessonId": 63}, {"id": "d13t2", "zh": "視覺語言模型", "en": "Vision-Language Model, VLM", "definition": "結合影像與語言能力，例如看圖問答。", "lessonId": 63}, {"id": "d13t3", "zh": "視覺語言動作模型", "en": "Vision-Language-Action Model, VLA", "definition": "結合視覺、語言與動作輸出，常用於機器人控制。", "lessonId": 63}, {"id": "d13t4", "zh": "文字生成影像", "en": "Text-to-Image, T2I", "definition": "依文字描述生成影像，例如把人物與場景描述轉成插畫。", "lessonId": 63}, {"id": "d13t5", "zh": "影像生成影像", "en": "Image-to-Image, I2I", "definition": "以原始影像為條件生成新的影像。", "lessonId": 63}, {"id": "d13t6", "zh": "文字生成影片", "en": "Text-to-Video, T2V", "definition": "依文字描述生成時間序列影像。", "lessonId": 63}, {"id": "d13t7", "zh": "影像生成影片", "en": "Image-to-Video, I2V", "definition": "以單張或多張影像作條件生成影片。", "lessonId": 63}, {"id": "d13t8", "zh": "文字生成音訊", "en": "Text-to-Audio", "definition": "依描述生成聲音內容，例如環境音。", "lessonId": 63}, {"id": "d13t9", "zh": "文字生成音樂", "en": "Text-to-Music", "definition": "依風格、節奏或內容描述生成音樂。", "lessonId": 63}, {"id": "d13t10", "zh": "生成對抗網路", "en": "Generative Adversarial Network, GAN", "definition": "以生成器與判別器的對抗學習產生資料。", "lessonId": 63}, {"id": "d13t11", "zh": "自動編碼器", "en": "Autoencoder, AE", "definition": "先編碼再解碼，學習重建輸入的模型。", "lessonId": 63}, {"id": "d13t12", "zh": "變分自動編碼器", "en": "Variational Autoencoder, VAE", "definition": "以變分推斷學習潛在變數分布的生成模型。", "lessonId": 64}, {"id": "d13t13", "zh": "擴散模型", "en": "Diffusion Model", "definition": "學習逆轉逐步加噪過程或相關去噪動態以生成資料。", "lessonId": 64}, {"id": "d13t14", "zh": "潛在擴散模型", "en": "Latent Diffusion Model, LDM", "definition": "在壓縮的潛在表示而非原始像素中執行擴散生成。", "lessonId": 64}, {"id": "d13t15", "zh": "擴散 Transformer", "en": "Diffusion Transformer, DiT", "definition": "使用 Transformer 作為擴散模型主要去噪骨幹。", "lessonId": 64}, {"id": "d13t16", "zh": "流匹配", "en": "Flow Matching", "definition": "學習把簡單分布運送到資料分布的速度場。", "lessonId": 64}, {"id": "d13t17", "zh": "潛在空間", "en": "Latent Space", "definition": "模型內部較抽象或壓縮的表示空間。", "lessonId": 64}, {"id": "d13t18", "zh": "潛在表示", "en": "Latent Representation", "definition": "資料在潛在空間中的編碼。", "lessonId": 64}, {"id": "d13t19", "zh": "加噪", "en": "Noise Addition", "definition": "依指定規則向資料或潛在表示加入雜訊。", "lessonId": 64}, {"id": "d13t20", "zh": "去噪", "en": "Denoising", "definition": "估計並移除雜訊，或預測與去噪相關的量。", "lessonId": 64}, {"id": "d13t21", "zh": "排程器", "en": "Scheduler", "definition": "生成情境中定義時間步、噪聲尺度及更新規則的元件。", "lessonId": 64}, {"id": "d13t22", "zh": "取樣器", "en": "Sampler", "definition": "依模型與數值更新方法產生樣本的程序。", "lessonId": 64}, {"id": "d13t23", "zh": "無分類器引導", "en": "Classifier-Free Guidance, CFG", "definition": "結合有條件與無條件預測調整條件遵循程度，過強可能降低品質。", "lessonId": 64}, {"id": "d13t24", "zh": "隨機種子", "en": "Random Seed", "definition": "控制偽隨機序列的起點；跨硬體與版本仍未必完全重現。", "lessonId": 65}, {"id": "d13t25", "zh": "負面提示詞", "en": "Negative Prompt", "definition": "用來指定不希望出現的內容，實際支援與效果依模型而定。", "lessonId": 65}, {"id": "d13t26", "zh": "影像修補", "en": "Inpainting", "definition": "在指定遮罩區域重建或生成影像內容。", "lessonId": 65}, {"id": "d13t27", "zh": "影像外擴", "en": "Outpainting", "definition": "生成原影像邊界之外的內容。", "lessonId": 65}, {"id": "d13t28", "zh": "控制條件", "en": "Conditioning", "definition": "用文字、深度、姿態或其他訊號引導生成。", "lessonId": 65}, {"id": "d13t29", "zh": "時間一致性", "en": "Temporal Consistency", "definition": "連續影格在身分、外觀與運動上的連貫程度。", "lessonId": 65}, {"id": "d13t30", "zh": "語音複製", "en": "Voice Cloning", "definition": "根據聲音樣本生成具有相似說話者特徵的語音。", "lessonId": 65}, {"id": "d13t31", "zh": "語音轉換", "en": "Voice Conversion", "definition": "保留語言內容並改變聲音特徵的技術。", "lessonId": 65}, {"id": "d13t32", "zh": "音源分離", "en": "Source Separation", "definition": "從混合音訊估計不同來源訊號。", "lessonId": 65}, {"id": "d13t33", "zh": "人聲分離", "en": "Vocal Separation", "definition": "從混音中估計人聲與伴奏等聲部。", "lessonId": 65}, {"id": "d13t34", "zh": "聲碼器", "en": "Vocoder", "definition": "在語音生成中常指把聲學特徵轉成波形的模型。", "lessonId": 65}, {"id": "d13t35", "zh": "世界模型", "en": "World Model", "definition": "學習環境狀態或動態，以預測行動後果、模擬或輔助規劃。", "lessonId": 65}], "level": "進階", "prerequisites": [4, 9, 12], "case": "以一張角色照片生成短影片：文字與影像提供條件，VAE 編碼進潛在空間，生成骨幹配合取樣更新生成影格。檢查角色一致性與動作連貫，再另做配音或音源分離，區分各模型負責的模態。", "exercises": ["畫出 T2I、I2V、TTS 與音源分離的輸入輸出表。", "固定模型與種子，比較取樣步數、CFG 與條件訊號對品質的影響。", "定義影片時間一致性與音訊可懂度的評估，不把生成細節視為原始證據。"], "pitfall": "相同種子跨硬體未必完全重現；VAE、DiT 與取樣器不是同一個元件。", "lessonIds": [63, 64, 65], "sourceIds": [3, 0]}, {"id": 14, "title": "強化學習與偏好對齊", "en": "Reinforcement Learning & Alignment", "terms": [{"id": "d14t0", "zh": "智能體／代理", "en": "Agent", "definition": "在強化學習中依觀察或狀態選擇動作的決策者。", "lessonId": 66}, {"id": "d14t1", "zh": "環境", "en": "Environment", "definition": "接受動作並回傳觀察、狀態或獎勵的外部系統。", "lessonId": 66}, {"id": "d14t2", "zh": "狀態", "en": "State", "definition": "用來描述環境決策情境的資訊，完整狀態可能無法直接觀測。", "lessonId": 66}, {"id": "d14t3", "zh": "觀察", "en": "Observation", "definition": "代理能實際取得的環境訊號，可能只是部分狀態。", "lessonId": 66}, {"id": "d14t4", "zh": "動作", "en": "Action", "definition": "代理在環境中可選擇執行的決策。", "lessonId": 66}, {"id": "d14t5", "zh": "獎勵", "en": "Reward", "definition": "對某次轉移或行為給予的即時數值回饋。", "lessonId": 66}, {"id": "d14t6", "zh": "策略", "en": "Policy", "definition": "由狀態或歷史資訊決定動作或動作分布的規則。", "lessonId": 66}, {"id": "d14t7", "zh": "回報", "en": "Return", "definition": "一段未來獎勵的累積，常使用折扣加權。", "lessonId": 66}, {"id": "d14t8", "zh": "價值函數", "en": "Value Function", "definition": "估計從某狀態開始、依策略行動的期望回報。", "lessonId": 67}, {"id": "d14t9", "zh": "動作價值函數", "en": "Action-Value Function / Q-Function", "definition": "估計在某狀態採特定動作後的期望回報。", "lessonId": 67}, {"id": "d14t10", "zh": "折扣因子", "en": "Discount Factor", "definition": "調整遠期獎勵權重的係數，常記為 γ。", "lessonId": 67}, {"id": "d14t11", "zh": "探索與利用", "en": "Exploration and Exploitation", "definition": "嘗試未知選項與使用已知高價值選項之間的取捨。", "lessonId": 67}, {"id": "d14t12", "zh": "馬可夫決策過程", "en": "Markov Decision Process, MDP", "definition": "以狀態、動作、轉移與獎勵等描述序列決策的數學框架。", "lessonId": 67}, {"id": "d14t13", "zh": "策略梯度", "en": "Policy Gradient", "definition": "直接依期望回報對策略參數的梯度改善策略。", "lessonId": 67}, {"id": "d14t14", "zh": "行動者－評論者", "en": "Actor–Critic", "definition": "結合選動作的策略模型與評估價值的模型。", "lessonId": 67}, {"id": "d14t15", "zh": "近端策略最佳化", "en": "Proximal Policy Optimization, PPO", "definition": "限制策略更新幅度的一類策略梯度方法，常見採裁剪目標。", "lessonId": 67}, {"id": "d14t16", "zh": "經驗回放", "en": "Experience Replay", "definition": "保存過去互動資料並重抽樣訓練，以提高資料利用率。", "lessonId": 68}, {"id": "d14t17", "zh": "獎勵模型", "en": "Reward Model", "definition": "預測輸出或行為偏好分數的模型，不等於客觀真理。", "lessonId": 68}, {"id": "d14t18", "zh": "人類回饋強化學習", "en": "Reinforcement Learning from Human Feedback, RLHF", "definition": "利用人類偏好等訊號建立獎勵並改善模型策略。", "lessonId": 68}, {"id": "d14t19", "zh": "AI 回饋強化學習", "en": "Reinforcement Learning from AI Feedback, RLAIF", "definition": "以 AI 評估提供部分或主要回饋訊號的對齊方法。", "lessonId": 68}, {"id": "d14t20", "zh": "直接偏好最佳化", "en": "Direct Preference Optimization, DPO", "definition": "直接用偏好配對目標調整策略，不需另跑傳統線上 RL 迴圈。", "lessonId": 68}, {"id": "d14t21", "zh": "可驗證獎勵強化學習", "en": "Reinforcement Learning with Verifiable Rewards, RLVR", "definition": "以可計算驗證的結果作獎勵，例如程式測試是否通過。", "lessonId": 68}, {"id": "d14t22", "zh": "獎勵駭取", "en": "Reward Hacking", "definition": "模型找到提高獎勵卻違背真正任務意圖的行為。", "lessonId": 68}], "level": "進階", "prerequisites": [0, 5], "case": "在小型格子環境中，代理選上下左右移動，環境回傳位置及獎勵。策略決定動作；價值估計未來回報。若只獎勵步數，代理可能拖延而不達成任務，說明獎勵設計可能被利用。", "exercises": ["定義格子任務的狀態、觀察、動作、轉移、獎勵與終止條件。", "比較 Policy Gradient、Actor–Critic、PPO 與 Experience Replay 的角色。", "比較 RLHF、RLAIF、DPO、RLVR 的回饋來源，設計可防獎勵駭取的驗證。"], "pitfall": "高獎勵不一定符合真正意圖；DPO 不需要傳統線上 RL 迴圈。", "lessonIds": [66, 67, 68], "sourceIds": [3, 0]}, {"id": 15, "title": "AI Agent、工具與 MCP", "en": "Agents, Tools & MCP", "terms": [{"id": "d15t0", "zh": "AI 智能代理", "en": "AI Agent", "definition": "結合模型、工具、狀態與控制流程來完成目標的系統。", "lessonId": 69}, {"id": "d15t1", "zh": "代理式 AI", "en": "Agentic AI", "definition": "能規劃、選工具或多步行動的 AI 系統設計取向。", "lessonId": 69}, {"id": "d15t2", "zh": "自主代理", "en": "Autonomous Agent", "definition": "在指定授權範圍內可自行選擇部分行動步驟的代理。", "lessonId": 69}, {"id": "d15t3", "zh": "多代理系統", "en": "Multi-Agent System, MAS", "definition": "多個代理協作、分工或互動的系統。", "lessonId": 69}, {"id": "d15t4", "zh": "工具", "en": "Tool", "definition": "代理可呼叫的具體操作，例如計算、檢索或寫入資料。", "lessonId": 69}, {"id": "d15t5", "zh": "工具呼叫", "en": "Tool Calling", "definition": "模型提出工具名稱與參數，由程式驗證並執行的流程。", "lessonId": 69}, {"id": "d15t6", "zh": "函數呼叫", "en": "Function Calling", "definition": "將模型需求轉成具結構的函數與參數呼叫。", "lessonId": 69}, {"id": "d15t7", "zh": "工具結構描述", "en": "Tool Schema", "definition": "描述工具名稱、用途、輸入型別與必要欄位的規格。", "lessonId": 69}, {"id": "d15t8", "zh": "規劃", "en": "Planning", "definition": "選擇達成目標的步驟、依賴與資源配置。", "lessonId": 69}, {"id": "d15t9", "zh": "任務分解", "en": "Task Decomposition", "definition": "把複雜目標拆成可管理的子任務。", "lessonId": 69}, {"id": "d15t10", "zh": "推理與行動", "en": "Reasoning and Acting, ReAct", "definition": "交替進行任務推理與工具或環境行動的代理模式。", "lessonId": 69}, {"id": "d15t11", "zh": "記憶", "en": "Memory", "definition": "在任務內或跨任務保存並取回相關資訊的機制。", "lessonId": 69}, {"id": "d15t12", "zh": "短期記憶", "en": "Short-Term Memory", "definition": "當次任務近期狀態或上下文資訊。", "lessonId": 70}, {"id": "d15t13", "zh": "長期記憶", "en": "Long-Term Memory", "definition": "可跨任務保留並再次檢索的資訊儲存。", "lessonId": 70}, {"id": "d15t14", "zh": "情節記憶", "en": "Episodic Memory", "definition": "以事件與經驗形式保存的紀錄。", "lessonId": 70}, {"id": "d15t15", "zh": "語意記憶", "en": "Semantic Memory", "definition": "以概念、事實與關係形式保存的知識。", "lessonId": 70}, {"id": "d15t16", "zh": "工作流程", "en": "Workflow", "definition": "定義步驟、條件與資料流的執行程序。", "lessonId": 70}, {"id": "d15t17", "zh": "流程編排", "en": "Orchestration", "definition": "協調模型、工具、代理與服務的執行與狀態。", "lessonId": 70}, {"id": "d15t18", "zh": "人工介入", "en": "Human-in-the-Loop, HITL", "definition": "在流程中加入人工決策、標註、確認或審核。", "lessonId": 70}, {"id": "d15t19", "zh": "人工審核", "en": "Human Review", "definition": "由人檢查結果或高影響操作是否可接受。", "lessonId": 70}, {"id": "d15t20", "zh": "狀態機", "en": "State Machine", "definition": "以有限狀態與轉移規則描述系統行為。", "lessonId": 70}, {"id": "d15t21", "zh": "交接", "en": "Handoff", "definition": "把任務與必要上下文轉給另一代理或人工處理。", "lessonId": 70}, {"id": "d15t22", "zh": "重試", "en": "Retry", "definition": "失敗後再次執行操作，需考量上限與重複副作用。", "lessonId": 70}, {"id": "d15t23", "zh": "冪等性", "en": "Idempotency", "definition": "相同操作重複執行對目標狀態的效果與一次相同。", "lessonId": 70}, {"id": "d15t24", "zh": "沙箱", "en": "Sandbox", "definition": "限制程式可存取的資源與權限的隔離環境。", "lessonId": 71}, {"id": "d15t25", "zh": "瀏覽器自動化", "en": "Browser Automation", "definition": "透過程式操作網頁的表單、導覽與互動。", "lessonId": 71}, {"id": "d15t26", "zh": "電腦操作", "en": "Computer Use", "definition": "以軟體控制使用者介面執行電腦任務。", "lessonId": 71}, {"id": "d15t27", "zh": "模型上下文協定", "en": "Model Context Protocol, MCP", "definition": "標準化應用與外部工具、資料等能力連接的協定，不是模型本身。", "lessonId": 71}, {"id": "d15t28", "zh": "MCP 主機", "en": "MCP Host", "definition": "管理用戶端連線與整合能力的 AI 應用。", "lessonId": 71}, {"id": "d15t29", "zh": "MCP 用戶端", "en": "MCP Client", "definition": "主機內與特定 MCP 伺服器維持協定連線的元件。", "lessonId": 71}, {"id": "d15t30", "zh": "MCP 伺服器", "en": "MCP Server", "definition": "向用戶端提供工具、資源或提示等能力的服務。", "lessonId": 71}, {"id": "d15t31", "zh": "資源", "en": "Resource", "definition": "MCP 中可供讀取並作為上下文的資料內容。", "lessonId": 71}, {"id": "d15t32", "zh": "連接器", "en": "Connector", "definition": "把應用與外部服務或資料來源接起來的整合元件。", "lessonId": 71}, {"id": "d15t33", "zh": "應用程式介面", "en": "Application Programming Interface, API", "definition": "軟體之間交換請求與結果的規格。", "lessonId": 71}, {"id": "d15t34", "zh": "應用程式開發套件", "en": "Software Development Kit, SDK", "definition": "協助使用某平台或 API 的程式庫與工具集合。", "lessonId": 71}, {"id": "d15t35", "zh": "技能", "en": "Skill", "definition": "在代理產品中通常指可重用的任務指引、資源或工具組合，具體格式依平台而異。", "lessonId": 71}], "level": "開發", "prerequisites": [10, 11], "case": "文件助理先規劃查詢，再呼叫搜尋工具，驗證參數後取得來源；草稿由人工審核後才可對外送出。MCP Host 管理應用內的 Client，Client 連到 Server 取得工具與資源，協定本身不會賦予寫入權限。", "exercises": ["畫出 Agent、Tool、Workflow 與 MCP Host–Client–Server 的關係。", "設計帶型別工具 schema、最小權限、超時、重試上限及冪等鍵。", "區分短期、長期、情節與語意記憶，規定可保存資料與人工交接條件。"], "pitfall": "工具呼叫是模型提出需求，實際執行與權限驗證由應用負責。", "lessonIds": [69, 70, 71], "sourceIds": [4, 3]}, {"id": 16, "title": "推論、硬體與效能", "en": "Inference, Hardware & Performance", "terms": [{"id": "d16t0", "zh": "推論", "en": "Inference", "definition": "使用已訓練模型計算輸出，不必更新模型參數。", "lessonId": 72}, {"id": "d16t1", "zh": "推論引擎", "en": "Inference Engine", "definition": "載入模型並安排推論運算的執行軟體。", "lessonId": 72}, {"id": "d16t2", "zh": "模型服務", "en": "Model Serving", "definition": "以介面提供模型推論，包含排程、擴縮與錯誤處理。", "lessonId": 72}, {"id": "d16t3", "zh": "延遲", "en": "Latency", "definition": "請求開始到指定完成點所需時間。", "lessonId": 72}, {"id": "d16t4", "zh": "吞吐量", "en": "Throughput", "definition": "單位時間可處理的請求、樣本或詞元數。", "lessonId": 72}, {"id": "d16t5", "zh": "首詞元時間", "en": "Time to First Token, TTFT", "definition": "從送出請求到收到第一個生成詞元的時間。", "lessonId": 72}, {"id": "d16t6", "zh": "詞元間延遲", "en": "Inter-Token Latency, ITL", "definition": "相鄰生成詞元之間的時間間隔。", "lessonId": 72}, {"id": "d16t7", "zh": "每秒詞元數", "en": "Tokens per Second, TPS", "definition": "生成或處理詞元的速率，需註明單請求或整體服務。", "lessonId": 72}, {"id": "d16t8", "zh": "批次推論", "en": "Batch Inference", "definition": "將多個輸入一起處理以提高資源利用率。", "lessonId": 72}, {"id": "d16t9", "zh": "動態批次", "en": "Dynamic Batching", "definition": "在服務時短暫聚合到達的請求組成批次。", "lessonId": 72}, {"id": "d16t10", "zh": "連續批次", "en": "Continuous Batching", "definition": "在生成過程中持續移除已完成請求並加入新請求。", "lessonId": 72}, {"id": "d16t11", "zh": "前綴快取", "en": "Prefix Caching", "definition": "重用相同提示前綴的計算結果以降低重複成本。", "lessonId": 73}, {"id": "d16t12", "zh": "推測解碼", "en": "Speculative Decoding", "definition": "用較便宜的草稿模型提議詞元，再由目標模型驗證以加速生成。", "lessonId": 73}, {"id": "d16t13", "zh": "邊緣 AI", "en": "Edge AI", "definition": "在接近資料來源的邊緣設備上執行 AI。", "lessonId": 73}, {"id": "d16t14", "zh": "裝置端 AI", "en": "On-Device AI", "definition": "在使用者或終端裝置本身執行模型。", "lessonId": 73}, {"id": "d16t15", "zh": "中央處理器", "en": "Central Processing Unit, CPU", "definition": "擅長通用控制與多種工作負載的處理器。", "lessonId": 73}, {"id": "d16t16", "zh": "圖形處理器", "en": "Graphics Processing Unit, GPU", "definition": "支援大量平行運算，常用於矩陣與張量工作負載。", "lessonId": 73}, {"id": "d16t17", "zh": "神經處理單元", "en": "Neural Processing Unit, NPU", "definition": "針對神經網路運算最佳化的硬體單元。", "lessonId": 73}, {"id": "d16t18", "zh": "張量處理器", "en": "Tensor Processing Unit, TPU", "definition": "針對機器學習張量運算設計的加速器名稱。", "lessonId": 73}, {"id": "d16t19", "zh": "顯示記憶體", "en": "Video Random Access Memory, VRAM", "definition": "GPU 可使用的記憶體，用於權重、激活與快取等。", "lessonId": 73}, {"id": "d16t20", "zh": "記憶體頻寬", "en": "Memory Bandwidth", "definition": "單位時間能傳送的記憶體資料量。", "lessonId": 73}, {"id": "d16t21", "zh": "浮點運算量", "en": "Floating-Point Operations, FLOPs", "definition": "完成計算所需的浮點運算數；FLOP/s 才是速率。", "lessonId": 73}, {"id": "d16t22", "zh": "資料平行", "en": "Data Parallelism", "definition": "各裝置保有模型副本並處理不同資料，再聚合梯度。", "lessonId": 74}, {"id": "d16t23", "zh": "模型平行", "en": "Model Parallelism", "definition": "把模型的不同部分分散到不同裝置。", "lessonId": 74}, {"id": "d16t24", "zh": "張量平行", "en": "Tensor Parallelism", "definition": "把單一層或張量運算切分到多個裝置。", "lessonId": 74}, {"id": "d16t25", "zh": "管線平行", "en": "Pipeline Parallelism", "definition": "把不同網路階段放到不同裝置，以微批次形成管線。", "lessonId": 74}, {"id": "d16t26", "zh": "分散式訓練", "en": "Distributed Training", "definition": "利用多個裝置或節點共同訓練模型。", "lessonId": 74}, {"id": "d16t27", "zh": "梯度檢查點", "en": "Gradient Checkpointing", "definition": "僅保存部分激活，在反向傳播重算其他激活以節省記憶體，不是保存模型檔案。", "lessonId": 74}, {"id": "d16t28", "zh": "激活值重計算", "en": "Activation Recomputation", "definition": "在需要時重新計算中間激活，以額外運算換取較低記憶體需求。", "lessonId": 74}, {"id": "d16t29", "zh": "記憶體卸載", "en": "Memory Offloading", "definition": "把部分權重、激活或最佳化器狀態移到 CPU 或其他儲存。", "lessonId": 74}, {"id": "d16t30", "zh": "記憶體不足", "en": "Out of Memory, OOM", "definition": "運算要求的記憶體超過可用容量而失敗。", "lessonId": 74}], "level": "開發", "prerequisites": [5, 9, 12], "case": "比較同一模型在不同批次下的 TTFT、ITL、TPS 與峰值 VRAM。總吞吐提高時，個別請求延遲可能變差；降低權重精度後，KV Cache 和激活仍會消耗記憶體，需量測整個工作負載。", "exercises": ["記錄硬體、輸入輸出長度、批次與精度，定義公平的效能測試。", "比較動態批次、連續批次、前綴快取與推測解碼作用於哪個瓶頸。", "為 OOM 設計縮小批次、重計算、卸載或平行化的取捨表。"], "pitfall": "FLOPs 是運算量，FLOP/s 是速率；梯度檢查點不是保存模型版本。", "lessonIds": [72, 73, 74], "sourceIds": [2]}, {"id": 17, "title": "安全、隱私與負責任 AI", "en": "Safety, Security & Responsible AI", "terms": [{"id": "d17t0", "zh": "負責任 AI", "en": "Responsible AI", "definition": "在設計、部署與治理中考慮公平、隱私、安全、透明與責任。", "lessonId": 75}, {"id": "d17t1", "zh": "AI 安全", "en": "AI Safety", "definition": "降低 AI 系統造成意外或不當傷害的風險。", "lessonId": 75}, {"id": "d17t2", "zh": "AI 資安", "en": "AI Security", "definition": "保護 AI 系統、資料與供應鏈免受惡意攻擊。", "lessonId": 75}, {"id": "d17t3", "zh": "AI 倫理", "en": "AI Ethics", "definition": "討論 AI 使用涉及的價值、權利與社會影響。", "lessonId": 75}, {"id": "d17t4", "zh": "公平性", "en": "Fairness", "definition": "評估不同個體或群體是否受到不合理差別影響，指標需配合情境。", "lessonId": 75}, {"id": "d17t5", "zh": "可解釋性", "en": "Explainability", "definition": "提供人可理解的理由或說明來解釋模型輸出。", "lessonId": 75}, {"id": "d17t6", "zh": "可詮釋性", "en": "Interpretability", "definition": "模型內部機制或表示可被人理解的程度；與可解釋性的用法常有重疊。", "lessonId": 75}, {"id": "d17t7", "zh": "透明度", "en": "Transparency", "definition": "清楚揭露系統用途、資料、限制與決策過程的程度。", "lessonId": 75}, {"id": "d17t8", "zh": "穩健性", "en": "Robustness", "definition": "在擾動、噪聲或條件變化下維持合理表現的能力。", "lessonId": 75}, {"id": "d17t9", "zh": "不確定性估計", "en": "Uncertainty Estimation", "definition": "估計預測不確定程度，而非只輸出單一答案。", "lessonId": 75}, {"id": "d17t10", "zh": "對抗樣本", "en": "Adversarial Example", "definition": "經特定擾動以誘使模型產生錯誤的輸入。", "lessonId": 75}, {"id": "d17t11", "zh": "對抗攻擊", "en": "Adversarial Attack", "definition": "利用模型或系統弱點操縱結果的攻擊方式。", "lessonId": 76}, {"id": "d17t12", "zh": "提示注入", "en": "Prompt Injection", "definition": "把惡意指令混入輸入，試圖改變系統原有任務或規則。", "lessonId": 76}, {"id": "d17t13", "zh": "間接提示注入", "en": "Indirect Prompt Injection", "definition": "將惡意指令藏在網頁、文件或工具結果等外部資料中。", "lessonId": 76}, {"id": "d17t14", "zh": "越獄", "en": "Jailbreak", "definition": "試圖使模型繞過原有安全或行為限制。", "lessonId": 76}, {"id": "d17t15", "zh": "資料投毒", "en": "Data Poisoning", "definition": "惡意修改訓練或其他學習資料以影響模型行為。", "lessonId": 76}, {"id": "d17t16", "zh": "模型投毒", "en": "Model Poisoning", "definition": "惡意操縱模型權重或更新，使系統產生攻擊者想要的行為。", "lessonId": 76}, {"id": "d17t17", "zh": "後門攻擊", "en": "Backdoor Attack", "definition": "讓模型遇到特定觸發條件時執行隱藏的惡意行為。", "lessonId": 76}, {"id": "d17t18", "zh": "模型竊取", "en": "Model Extraction", "definition": "透過查詢等方式複製模型能力或近似其行為。", "lessonId": 76}, {"id": "d17t19", "zh": "成員推斷攻擊", "en": "Membership Inference Attack", "definition": "推斷某筆資料是否曾用於訓練特定模型。", "lessonId": 76}, {"id": "d17t20", "zh": "模型反演", "en": "Model Inversion", "definition": "從模型資訊推估輸入資料或其敏感特徵。", "lessonId": 76}, {"id": "d17t21", "zh": "個人可識別資訊", "en": "Personally Identifiable Information, PII", "definition": "可直接或間接識別個人的資訊。", "lessonId": 76}, {"id": "d17t22", "zh": "差分隱私", "en": "Differential Privacy", "definition": "對單筆資料是否存在所造成的輸出分布差異給予數學限制。", "lessonId": 77}, {"id": "d17t23", "zh": "最小權限原則", "en": "Principle of Least Privilege", "definition": "只授予完成任務所必需的最小存取能力。", "lessonId": 77}, {"id": "d17t24", "zh": "內容審核", "en": "Content Moderation", "definition": "依政策辨識、標記或限制不適當內容。", "lessonId": 77}, {"id": "d17t25", "zh": "安全防護機制", "en": "Guardrails", "definition": "以驗證、過濾、權限與流程約束系統行為，不能只靠提示詞。", "lessonId": 77}, {"id": "d17t26", "zh": "紅隊測試", "en": "Red Teaming", "definition": "主動尋找系統失敗模式與可利用弱點的測試。", "lessonId": 77}, {"id": "d17t27", "zh": "深度偽造", "en": "Deepfake", "definition": "利用生成技術製作或操縱容易被誤認為真實的影音內容。", "lessonId": 77}, {"id": "d17t28", "zh": "內容溯源", "en": "Content Provenance", "definition": "記錄內容來源、修改歷史與產生方式。", "lessonId": 77}, {"id": "d17t29", "zh": "浮水印", "en": "Watermarking", "definition": "在內容中加入可檢測訊號，效果與抗移除能力依方法而異。", "lessonId": 77}, {"id": "d17t30", "zh": "模型卡", "en": "Model Card", "definition": "說明模型用途、訓練背景、評估與限制的文件。", "lessonId": 77}, {"id": "d17t31", "zh": "資料集說明文件", "en": "Dataset Datasheet", "definition": "記錄資料蒐集、組成、處理、授權及限制的文件。", "lessonId": 77}, {"id": "d17t32", "zh": "人工監督", "en": "Human Oversight", "definition": "由人監察、介入或負責系統運作與影響的安排。", "lessonId": 77}], "level": "開發", "prerequisites": [1, 15], "case": "RAG 文件中藏有要求外傳資料的句子，應把它當成不可信文件內容。檢索先檢查權限，工具執行前驗證目的與參數，敏感操作需明確授權，紀錄中則避免保存不必要的 PII。", "exercises": ["以提示注入、資料投毒、模型竊取分類威脅，說明攻擊發生的階段。", "列出最小權限、沙箱、人工審核與紅隊測試各自能處理的風險。", "撰寫模型卡與資料說明，定義公平、隱私、不確定性及內容溯源的檢查。"], "pitfall": "安全、資安與倫理相關但不同；Guardrails 不能只依賴系統提示詞。", "lessonIds": [75, 76, 77], "sourceIds": [3, 0]}, {"id": 18, "title": "工程、部署與維運", "en": "Engineering, Deployment & Operations", "terms": [{"id": "d18t0", "zh": "機器學習維運", "en": "Machine Learning Operations, MLOps", "definition": "管理資料、實驗、模型交付與監測的工程實務。", "lessonId": 78}, {"id": "d18t1", "zh": "大型語言模型維運", "en": "Large Language Model Operations, LLMOps", "definition": "將語言模型、提示、檢索、評估與服務納入版本化維運。", "lessonId": 78}, {"id": "d18t2", "zh": "資料管線", "en": "Data Pipeline", "definition": "自動執行蒐集、轉換、檢查與傳送資料的一系列步驟。", "lessonId": 78}, {"id": "d18t3", "zh": "訓練管線", "en": "Training Pipeline", "definition": "串接資料準備、訓練、驗證與模型產物管理的流程。", "lessonId": 78}, {"id": "d18t4", "zh": "推論管線", "en": "Inference Pipeline", "definition": "串接輸入處理、模型運算、後處理與輸出驗證的流程。", "lessonId": 78}, {"id": "d18t5", "zh": "實驗追蹤", "en": "Experiment Tracking", "definition": "記錄配置、程式版本、資料版本、指標與產物。", "lessonId": 78}, {"id": "d18t6", "zh": "模型登錄庫", "en": "Model Registry", "definition": "集中管理模型版本、狀態與部署相關中繼資料。", "lessonId": 78}, {"id": "d18t7", "zh": "模型版本管理", "en": "Model Versioning", "definition": "為權重、配置與相依資訊建立可追溯版本。", "lessonId": 78}, {"id": "d18t8", "zh": "資料版本管理", "en": "Data Versioning", "definition": "保存資料與其處理規則的版本關係。", "lessonId": 79}, {"id": "d18t9", "zh": "可重現性", "en": "Reproducibility", "definition": "在記錄條件下能重做實驗並得到可比較結果的能力。", "lessonId": 79}, {"id": "d18t10", "zh": "容器化", "en": "Containerization", "definition": "封裝應用與相依環境以提高部署一致性。", "lessonId": 79}, {"id": "d18t11", "zh": "持續整合", "en": "Continuous Integration, CI", "definition": "頻繁整合程式變更並自動執行檢查。", "lessonId": 79}, {"id": "d18t12", "zh": "持續交付", "en": "Continuous Delivery, CD", "definition": "讓通過檢查的版本隨時可發布，正式發布可有人工決定。", "lessonId": 79}, {"id": "d18t13", "zh": "持續部署", "en": "Continuous Deployment", "definition": "通過既定檢查後自動發布到正式環境。", "lessonId": 79}, {"id": "d18t14", "zh": "模型監測", "en": "Model Monitoring", "definition": "追蹤效能、資料變化、失敗與成本等部署後指標。", "lessonId": 79}, {"id": "d18t15", "zh": "可觀測性", "en": "Observability", "definition": "透過紀錄、指標與追蹤理解系統內部狀況的能力。", "lessonId": 79}, {"id": "d18t16", "zh": "追蹤紀錄", "en": "Trace", "definition": "記錄單一請求跨元件與工具步驟的執行路徑。", "lessonId": 80}, {"id": "d18t17", "zh": "A/B 測試", "en": "A/B Testing", "definition": "把流量分派到不同版本，比較預先定義的結果。", "lessonId": 80}, {"id": "d18t18", "zh": "金絲雀部署", "en": "Canary Deployment", "definition": "先向小部分流量發布新版本，觀察後逐步擴大。", "lessonId": 80}, {"id": "d18t19", "zh": "影子部署", "en": "Shadow Deployment", "definition": "把真實請求副本送到新系統評估，但不讓新結果影響正式回覆。", "lessonId": 80}, {"id": "d18t20", "zh": "回滾", "en": "Rollback", "definition": "把服務恢復到已知可用的先前版本。", "lessonId": 80}, {"id": "d18t21", "zh": "速率限制", "en": "Rate Limiting", "definition": "限制某時間範圍的請求或資源消耗。", "lessonId": 80}, {"id": "d18t22", "zh": "成本最佳化", "en": "Cost Optimization", "definition": "在品質、延遲與資源限制下調整系統以降低總成本。", "lessonId": 80}], "level": "開發", "prerequisites": [6, 15, 16, 17], "case": "將文件問答部署到服務：CI 檢查程式與資料格式，評估通過後先以影子流量觀察，再做小比例金絲雀發布。模型、提示、索引、資料與配置都需版本化，品質或延遲變差時能回滾相容版本。", "exercises": ["列出資料、訓練、推論三條管線的輸入、產物與驗證。", "比較 CI、Continuous Delivery、Continuous Deployment 的自動化邊界。", "制定 A/B、監測、速率限制及回滾方案，定義品質與成本警戒線。"], "pitfall": "影子部署不影響正式回覆；只回滾模型而不回滾不相容索引可能仍然失敗。", "lessonIds": [78, 79, 80], "sourceIds": [3, 0]}];
